	c := mustCourt(courtSlug)
	pts, more := collectSeriesKeyed(c.csArch, &c.priceH, priceSeriesKey)
	return formatSeries(epochBlocks, uint32(heightNow()/epochBlocks)+1, pts, more)
}

package kourt
import (
	"time"
	runtime "chain/runtime"
	unsafe "chain/runtime/unsafe"
)
const (
	maxAdvanceStep  = int64(10 * 365 * 86400)
	maxAdvanceTotal = int64(100 * 365 * 86400)
	maxHeightStep  = 2 * periodBlocks
	maxHeightTotal = 10 * periodBlocks
	maxBase = int64(4102444800)
)
var (
	tcDeployer address
	tcArmed    bool
	tcSealed   bool
	tcSkew     int64
	tcBase     int64
	tcFloor    int64
	tcEverArmed bool
	tcPeakSkew  int64
	tcHeightSkew int64
	tcHeightPeak int64
	tcHeightBase  int64
	tcHeightFloor int64
)
func init() { tcDeployer = unsafe.OriginCaller() }
func mustDeployer(cur realm) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	if cur.Previous().Address() != tcDeployer {
		panic("kourtv2: only the deployer may drive the test clock")
	}
}
func EnableTestClock(cur realm) {
	mustDeployer(cur)
	if tcSealed {
		panic("kourtv2: the test clock is sealed; this realm is not a test chain")
	}
	if tcArmed {
		panic("kourtv2: the test clock is already armed")
	}
	if CourtCount() > 2 {
		panic("kourtv2: this realm already has courts; the test clock cannot be armed")
	}
	m := mustCourt(metaSlug)
	if m.nextID > 1 || m.coin.TotalSupply() > 0 {
		panic("kourtv2: this realm has been used; the test clock cannot be armed")
	}
	tcArmed = true
	tcBase = time.Now().Unix()
	if tcBase > maxBase {
		panic("kourtv2: this chain's own clock reads past 2100; check its genesis time")
	}
	tcFloor = tcBase
	tcHeightBase = runtime.ChainHeight()
	tcHeightFloor = tcHeightBase
}
func EnableTestClockAt(cur realm, base int64) {
	mustDeployer(cur)
	if base <= 0 {
		panic("kourtv2: the test clock's base must be a positive instant")
	}
	if base > maxBase {
		panic("kourtv2: the test clock's base must be an instant before 2100")
	}
	EnableTestClock(cur)
	tcBase = base
	if base > tcFloor {
		tcFloor = base
	}
}
func AdvanceTestClock(cur realm, secs int64) {
	mustDeployer(cur)
	if !tcArmed {
		panic("kourtv2: the test clock is not armed")
	}
	if secs <= 0 || secs > maxAdvanceStep {
		panic("kourtv2: the test clock moves forward, by at most ten years a step")
	}
	if tcSkew > maxAdvanceTotal-secs {
		panic("kourtv2: the test clock has advanced as far as it may")
	}
	tcSkew += secs
	if tcSkew > tcPeakSkew {
		tcPeakSkew = tcSkew
	}
	if n := tcBase + tcSkew; n > tcFloor {
		tcFloor = n
	}
}
func AdvanceTestHeight(cur realm, n int64) {
	mustDeployer(cur)
	if !tcArmed {
		panic("kourtv2: the test clock is not armed")
	}
	if n <= 0 || n > maxHeightStep {
		panic("kourtv2: the test height moves forward, by at most two emission periods a step")
	}
	if tcHeightSkew > maxHeightTotal-n {
		panic("kourtv2: the test height has advanced as far as it may")
	}
	tcHeightSkew += n
	if tcHeightSkew > tcHeightPeak {
		tcHeightPeak = tcHeightSkew
	}
	if h := tcHeightBase + tcHeightSkew; h > tcHeightFloor {
		tcHeightFloor = h
	}
}
func TestHeightSkew() int64 { return tcHeightSkew }
func TestHeightPeakSkew() int64 { return tcHeightPeak }
func SealTestClock(cur realm) {
	mustDeployer(cur)
	if !tcArmed {
		panic("kourtv2: the test clock was never armed; there is nothing to seal")
	}
	sealTestClock()
}
func sealTestClock() {
	tcSealed = true
	tcArmed = false
	tcSkew = 0
	tcBase = 0
	tcHeightSkew = 0
}
func TestClockActive() bool { return tcArmed }
func TestClockFabricated() bool { return tcEverArmed }
func TestClockSkew() int64 { return tcSkew }
func TestClockPeakSkew() int64 { return tcPeakSkew }
func tcNow() int64 {
	var n int64
	if tcArmed {
		n = tcBase + tcSkew
	} else {
		n = time.Now().Unix()
		if n < tcFloor {
			n = tcFloor
		}
	}
	if n <= 0 {
		panic("kourtv2: the clock read a non-positive instant")
	}
	return n
}

package kourt
func tierBpsFor(cs *claimState) int64 {
	if cs.tierRef <= 0 {
		return tierParBps
	}
	v := mulDiv128(cs.xBarFrozen, tierParBps, cs.tierRef)
	if v < tierFloorBps {
		return tierFloorBps
	}
	if v > tierCeilBps {
		return tierCeilBps
	}
	return v
}
func tierRefAt(c *Court) int64 {
	ref := c.xBarAcc / tierEMAN
	if floor := supplyFloor(c, tierRefFloorBps, tierRefDustCC); ref < floor {
		ref = floor
	}
	return ref
}
func observeClaimSize(c *Court, xbar int64) {
	c.xBarAcc = mustAdd(c.xBarAcc, xbar-c.xBarAcc/tierEMAN)
}
func ClaimTierBps(courtSlug string, claimID uint64) int64 {
	return tierBpsFor(mustClaim(mustCourt(courtSlug), claimID))
}
func ClaimTierRef(courtSlug string, claimID uint64) int64 {
	return mustClaim(mustCourt(courtSlug), claimID).tierRef
}
func spamNetBps(cs *claimState) int64 {
	if cs.spamTotalW <= 0 {
		return tierParBps
	}
	net := cs.spamTotalW - mustMul(2, cs.spamW)
	if net <= 0 {
		return 0
	}
	return mulDiv128(net, tierParBps, cs.spamTotalW)
}

package kourt
import "gno.land/p/nt/bptree/v0"
const (
	voteLockDispute  = "d"
	voteLockElection = "e"
)
func voteLockKey(who address, kind string, id, sub uint64) string {
	return string(who) + kind + beClaimKey(id) + beClaimKey(sub)
}
func voteLockParts(who address, key string) (kind string, id, sub uint64, ok bool) {
	tail := key[len(string(who)):]
	if len(tail) != 1+8+8 {
		return "", 0, 0, false
	}
	return tail[0:1], beClaimID(tail[1:9]), beClaimID(tail[9:17]), true
}
func voteLockOpen(c *Court, who address, key string) bool {
	kind, id, sub, ok := voteLockParts(who, key)
	if !ok {
		return false
	}
	switch kind {
	case voteLockDispute:
		v := c.claims.Get(beClaimKey(id))
		if v == nil {
			return false
		}
		cs := v.(*claimState)
		return cs.disputeOpen && cs.proposalID == int64(sub)
	case voteLockElection:
		if c.mod == nil || c.mod.election == nil {
			return false
		}
		e := c.mod.election
		return e.seq == id && !e.resolved
	}
	return false
}
func voteLockedOf(c *Court, who address) int64 {
	if c.voteLocks == nil {
		return 0
	}
	var most int64
	pre := string(who)
	c.voteLocks.Iterate(pre, pre+"\xff", func(k string, v any) bool {
		if w := v.(int64); w > most && voteLockOpen(c, who, k) {
			most = w
		}
		return false
	})
	return most
}
func lockVote(c *Court, who address, kind string, id, sub, amount int64) {
	if amount <= 0 {
		return
	}
	if c.voteLocks == nil {
		c.voteLocks = bptree.NewBPTree32()
	}
	pruneVoteLocks(c, who)
	c.voteLocks.Set(voteLockKey(who, kind, uint64(id), uint64(sub)), amount)
}
func pruneVoteLocks(c *Court, who address) int {
	if c.voteLocks == nil {
		return 0
	}
	var stale []string
	pre := string(who)
	c.voteLocks.Iterate(pre, pre+"\xff", func(k string, _ any) bool {
		if _, _, _, ok := voteLockParts(who, k); !ok {
			return false
		}
		if !voteLockOpen(c, who, k) {
			stale = append(stale, k)
		}
		return false
	})
	for _, k := range stale {
		c.voteLocks.Remove(k)
	}
	return len(stale)
}
func beClaimID(s string) uint64 {
	var v uint64
	for i := 0; i < 8; i++ {
		v = v<<8 | uint64(s[i])
	}
	return v
}
func PruneVoteLocks(cur realm, courtSlug string, who address) int {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	if !who.IsValid() {
		panic("kourtv2: that is not a valid address")
	}
	return pruneVoteLocks(mustCourt(courtSlug), who)
}
func CommitmentsOf(courtSlug string, who address) string {
	c := mustCourt(courtSlug)
	out := "stake:" + itoa(lockedOf(c, who)) +
		";vote:" + itoa(voteLockedOf(c, who)) +
		";free:" + itoa(disposable(c, who))
	if c.voteLocks == nil {
		return out
	}
	pre := string(who)
	c.voteLocks.Iterate(pre, pre+"\xff", func(k string, v any) bool {
		if !voteLockOpen(c, who, k) {
			return false
		}
		kind, id, sub, ok := voteLockParts(who, k)
		if !ok {
			return false
		}
		out += ";q:" + kind + ":" + itoa(int64(id)) + ":" + itoa(int64(sub)) +
			":" + itoa(v.(int64))
		return false
	})
	return out
}
func VoteLockedOf(courtSlug string, who address) int64 {
	return voteLockedOf(mustCourt(courtSlug), who)
}

package kourt
func votingWeight(c *Court, who address, at uint32) (w, snapshot int64) {
	snapshot = c.coin.PastVotes(who, at)
	w = snapshot
	if held := c.coin.BalanceOf(who); held < w {
		w = held
	}
	if w < 0 {
		w = 0
	}
	return w, snapshot
}
func voteCap(c *Court, who address) int64 { return c.coin.BalanceOf(who) }
func ClaimVoteWeightOf(courtSlug string, who address, claimID uint64) (verdict, quality int64) {
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if cs.disputeOpen {
		verdict, _ = votingWeight(c, who, c.gov.EpochOf(cs.proposalID))
	}
	return verdict, quality
}
func ElectionVoteWeightOf(courtSlug string, who address) int64 {
	c := mustCourt(courtSlug)
	if c.mod == nil || c.mod.election == nil || c.mod.election.resolved {
		return 0
	}
	e := c.mod.election
	if prior := e.voters.Get(who.String()); prior != nil {
		return prior.(int64)
	}
	w, _ := votingWeight(c, who, e.epoch)
	return w
}
func VoteWeightWhy(courtSlug string, who address, claimID uint64) (verdict, quality string) {
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	verdict = "no verdict vote is open on this claim"
	if cs.disputeOpen {
		verdict = whyWeighed(c, who, c.gov.EpochOf(cs.proposalID))
	}
	quality = "the quality vote no longer exists"
	return verdict, quality
}
func whyWeighed(c *Court, who address, at uint32) string {
	w, snapshot := votingWeight(c, who, at)
	switch {
	case snapshot <= 0:
		return "you had none when this vote started; coin bought since counts in later votes"
	case w <= 0:
		return "you had some when this vote started but have none now, and your say is the smaller of the two"
	case w < snapshot:
		return "limited to what you still hold, which is less than when this vote started"
	}
	return "counted in full"
}

package kourt
const answerWindow = 3 * epochBlocks
func PostAnswer(cur realm, courtSlug string, claimID uint64, verdict int) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	mustSide(verdict)
	if cs.closed {
		panic("kourtv2: this claim is closed")
	}
	if cs.frozenAt != 0 {
		panic("kourtv2: this claim already has an answer")
	}
	now := heightNow()
	if passed, known := pastDeadline(cs.openedAtTime, deadClaimSecs); (known && passed) ||
		(!known && now >= cs.openedAt+deadClaimTimeout) {
		panic("kourtv2: this claim is past the dead-claim timeout; it closes, it is not answered")
	}
	xbar, mature := cs.oi.Average(now, answerWindow)
	if !mature {
		panic("kourtv2: not enough stake history to answer yet")
	}
	if xbar < effMinAnswerX(c) {
		panic("kourtv2: trailing stake is below the minimum to answer")
	}
	inPriority := false
	if passed, known := pastDeadline(cs.openedAtTime,
		blocksToSecs(c.params.stakeOpenDelayBlocks+answerWindow)+priorityWindowSecs); priorityGateActive(c) &&
		((known && !passed) ||
			(!known && now < cs.openedAt+c.params.stakeOpenDelayBlocks+answerWindow+priorityWindowBlocks)) {
		if !mayAnswerInPriority(c, who) {
			panic("kourtv2: the priority window is open — a qualified answerer may act first (wait ~24h)")
		}
		inPriority = true
	}
	touch(c)
	advancePools(c, cs)
	if life := lifeAvgStake(cs, now); life > xbar {
		xbar = life
	}
	bond := xbar * answerBondBps / 10000
	if c.params.answerBondCapCC > 0 && bond > c.params.answerBondCapCC {
		bond = c.params.answerBondCapCC
	}
	convHi, convLo := cs.sideConv(verdict)
	floor := bondFloorAt(xbar, convHi, convLo)
	oppHi, oppLo := cs.sideConv(oppositeSide(verdict))
	if opp := bondFloorAt(xbar, oppHi, oppLo); opp > floor {
		floor = opp
	}
	if floor > bond {
		bond = floor
	}
	if bond < 1 {
		bond = 1
	}
	mustSpendable(c, who, bond)
	c.coin.Transfer(who, c.escrow, bond)
	cs.frozenAt = now
	cs.rateAccAtFreeze = c.rateAccFP
	cs.xBarFrozen = xbar
	cs.tierRef = tierRefAt(c)
	observeClaimSize(c, xbar)
	cs.yesStakeAtFreeze, cs.noStakeAtFreeze = cs.yesStake, cs.noStake
	cs.answer = int8(verdict)
	cs.answerer = who
	cs.answerBond = bond
	cs.answerBond0 = bond
	cs.answerHeight = now
	cs.answeredAtTime = nowTime()
	if inPriority {
		holdPriority(c, who, claimID)
	}
	pendingExit(c, cs)
	stripEnter(c, cs)
	onClaimAnswered(c, cs)
}
func HasAnswer(courtSlug string, claimID uint64) bool {
	return mustClaim(mustCourt(courtSlug), claimID).frozenAt != 0
}
func AnswerVerdict(courtSlug string, claimID uint64) int {
	cs := mustClaim(mustCourt(courtSlug), claimID)
	if cs.frozenAt == 0 {
		panic("kourtv2: no answer yet")
	}
	return int(cs.answer)
}
func AnswerBond(courtSlug string, claimID uint64) int64 {
	return mustClaim(mustCourt(courtSlug), claimID).answerBond
}
func Answerer(courtSlug string, claimID uint64) address {
	return mustClaim(mustCourt(courtSlug), claimID).answerer
}
func XBarFrozen(courtSlug string, claimID uint64) int64 {
	return mustClaim(mustCourt(courtSlug), claimID).xBarFrozen
}

package kourt
func settleAnswerBond(c *Court, cs *claimState) {
	c.coin.Transfer(c.escrow, cs.answerer, cs.answerBond)
	cs.answerBond = 0
}
func (cs *claimState) sideConv(side int) (hi, lo uint64) {
	if side == sideYES {
		return cs.yesConvHi, cs.yesConvLo
	}
	return cs.noConvHi, cs.noConvLo
}
func bondFloorAt(xbar int64, convHi, convLo uint64) int64 {
	flat := xbar * bondFloorFlatBps / 10000
	if draw := mulDiv128(convToCC(convHi, convLo), bondFloorConvBps, 10000); draw > flat {
		return draw
	}
	return flat
}
func bondFloorFor(cs *claimState) int64 {
	hi, lo := cs.sideConv(int(cs.answer))
	return bondFloorAt(cs.xBarFrozen, hi, lo)
}

package kourt
import (
	"strconv"
	"strings"
	bptree "gno.land/p/nt/bptree/v0"
)
const (
	assocSupports = int8(0)
	assocContests = int8(1)
	maxAssocOut = 32
	maxAssocIn  = 64
	maxAssocInPerAuthor = 4
)
const assocBondDefaultInit = int64(1_000_000)
var assocBondDefault = assocBondDefaultInit
func assocBondFor(c *Court) int64 {
	if c.assocBond > 0 {
		return c.assocBond
	}
	return assocBondDefault
}
func SetAssociationBondDefault(cur realm, amount int64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	d := ensureGlobalDAO()
	if cur.Previous().Address() != d.admin {
		panic("kourtv2: only the global DAO admin sets the default association bond")
	}
	if amount < 0 {
		panic("kourtv2: an association bond cannot be negative")
	}
	assocBondDefault = amount
}
func SetCourtAssociationBond(cur realm, courtSlug string, amount int64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	requireActiveMod(ensureMod(c), who)
	if amount < 0 {
		panic("kourtv2: an association bond cannot be negative")
	}
	c.assocBond = amount
}
func AssociationBond(courtSlug string) int64 { return assocBondFor(mustCourt(courtSlug)) }
func AssociationBondDefault() int64 { return assocBondDefault }
const assocBondWindowSecs = int64(14 * 86400)
func mustAssocEdge(c *Court, from, to uint64) *assocEdge {
	if c.assocOut == nil {
		panic("kourtv2: no such association")
	}
	v := c.assocOut.Get(assocKey(from, to))
	if v == nil {
		panic("kourtv2: no such association")
	}
	return v.(*assocEdge)
}
func dropAssocEdge(c *Court, from, to uint64) {
	c.assocOut.Remove(assocKey(from, to))
	c.assocIn.Remove(assocKey(to, from))
}
func burnAssocBond(c *Court, e *assocEdge) {
	amt := e.bond
	e.bond = 0
	c.coin.Burn(c.escrow, amt)
}
func releaseAssocBond(c *Court, e *assocEdge) {
	if e.bond <= 0 {
		return
	}
	amt := e.bond
	e.bond = 0
	c.coin.Transfer(c.escrow, e.author, amt)
}
func ApproveAssociation(cur realm, courtSlug string, from, to uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	requireActiveMod(ensureMod(c), who)
	e := mustAssocEdge(c, from, to)
	if e.bond <= 0 {
		panic("kourtv2: no bond is held on that edge")
	}
	releaseAssocBond(c, e)
}
func DisapproveAssociation(cur realm, courtSlug string, from, to uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	requireActiveMod(ensureMod(c), who)
	e := mustAssocEdge(c, from, to)
	if e.bond <= 0 {
		panic("kourtv2: no bond is held on that edge; remove it instead")
	}
	burnAssocBond(c, e)
	dropAssocEdge(c, from, to)
}
func ClaimAssociationBond(cur realm, courtSlug string, from, to uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	e := mustAssocEdge(c, from, to)
	if e.bond <= 0 {
		panic("kourtv2: no bond is held on that edge")
	}
	if e.author != who {
		panic("kourtv2: only the edge's author may take its bond back")
	}
	if nowTime() < e.bondUntil {
		panic("kourtv2: the moderation window on that bond has not closed yet")
	}
	releaseAssocBond(c, e)
}
func pendingIncident(c *Court, claimID uint64) ([]uint64, []uint64) {
	outs, ins := []uint64{}, []uint64{}
	if c.assocOut == nil {
		return outs, ins
	}
	p := beClaimKey(claimID)
	c.assocOut.Iterate(p, "", func(key string, v any) bool {
		if !strings.HasPrefix(key, p) {
			return true
		}
		if e := v.(*assocEdge); e.bond > 0 {
			outs = append(outs, claimIDFromKey(key[8:]))
		}
		return false
	})
	c.assocIn.Iterate(p, "", func(key string, v any) bool {
		if !strings.HasPrefix(key, p) {
			return true
		}
		if e := v.(*assocEdge); e.bond > 0 {
			ins = append(ins, claimIDFromKey(key[8:]))
		}
		return false
	})
	return outs, ins
}
func ApproveAllAssociations(cur realm, courtSlug string, claimID uint64) int {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	requireActiveMod(ensureMod(c), who)
	mustClaim(c, claimID)
	outs, ins := pendingIncident(c, claimID)
	n := 0
	for _, to := range outs {
		releaseAssocBond(c, mustAssocEdge(c, claimID, to))
		n++
	}
	for _, from := range ins {
		releaseAssocBond(c, mustAssocEdge(c, from, claimID))
		n++
	}
	return n
}
func DisapproveAllAssociations(cur realm, courtSlug string, claimID uint64, reason string) int {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := ensureMod(c)
	requireActiveMod(cm, who)
	checkReason(reason)
	mustClaim(c, claimID)
	key := "assocburn:" + strconv.FormatUint(claimID, 10)
	opened := pendingOpenedAt(cm.pending, key)
	fire, _ := approveAction(cm.pending, key, who, reason, cm.m)
	if !fire {
		return 0
	}
	if opened == 0 {
		opened = heightNow()
	}
	outs, ins := pendingIncident(c, claimID)
	n := 0
	for _, to := range outs {
		n += burnIfOlder(c, claimID, to, opened)
	}
	for _, from := range ins {
		n += burnIfOlder(c, from, claimID, opened)
	}
	return n
}
func burnIfOlder(c *Court, from, to uint64, opened int64) int {
	e := mustAssocEdge(c, from, to)
	if e.bond <= 0 || e.at > opened {
		return 0
	}
	burnAssocBond(c, e)
	dropAssocEdge(c, from, to)
	return 1
}
type assocEdge struct {
	bond int64
	bondUntil int64
	stance int8
	author address
	at int64
}
func ensureAssocs(c *Court) {
	if c.assocOut == nil {
		c.assocOut = bptree.NewBPTree32()
	}
	if c.assocIn == nil {
		c.assocIn = bptree.NewBPTree32()
	}
}
func assocKey(a, b uint64) string { return beClaimKey(a) + beClaimKey(b) }
func assocTextGone(c *Court, id uint64) bool {
	if c.mod == nil {
		return false
	}
	clm := lookupClaimMod(c.mod, id)
	return clm != nil && (clm.purged || clm.global)
}
func AddAssociation(cur realm, courtSlug string, from, to uint64, stance string) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	if from == to {
		panic("kourtv2: a claim cannot bear on itself")
	}
	var st int8
	switch stance {
	case "supports":
		st = assocSupports
	case "contests":
		st = assocContests
	default:
		panic("kourtv2: a stance is \"supports\" or \"contests\"")
	}
	f := mustClaim(c, from)
	mustClaim(c, to)
	bond := int64(0)
	if f.author != who && !isActiveMod(ensureMod(c), who) {
		bond = assocBondFor(c)
	}
	ensureAssocs(c)
	k := assocKey(from, to)
	if c.assocOut.Get(k) != nil {
		panic("kourtv2: that edge already exists; remove it to change its stance")
	}
	outN := 0
	c.assocOut.Iterate(beClaimKey(from), "", func(key string, _ any) bool {
		if !strings.HasPrefix(key, beClaimKey(from)) {
			return true
		}
		outN++
		return outN > maxAssocOut
	})
	if outN >= maxAssocOut {
		panic("kourtv2: this claim already asserts " + strconv.Itoa(maxAssocOut) + " associations")
	}
	inN, mine := 0, 0
	c.assocIn.Iterate(beClaimKey(to), "", func(key string, v any) bool {
		if !strings.HasPrefix(key, beClaimKey(to)) {
			return true
		}
		inN++
		if e, ok := v.(*assocEdge); ok && e.author == who {
			mine++
		}
		return false
	})
	if inN >= maxAssocIn {
		panic("kourtv2: that claim already carries " + strconv.Itoa(maxAssocIn) + " associations")
	}
	if mine >= maxAssocInPerAuthor {
		panic("kourtv2: you already hold " + strconv.Itoa(maxAssocInPerAuthor) +
			" associations on that claim")
	}
	if bond > 0 {
		mustSpendable(c, who, bond)
		c.coin.Transfer(who, c.escrow, bond)
	}
	e := &assocEdge{stance: st, author: who, at: heightNow(), bond: bond}
	if bond > 0 {
		e.bondUntil = nowTime() + assocBondWindowSecs
	}
	c.assocOut.Set(k, e)
	c.assocIn.Set(assocKey(to, from), e)
}
func RemoveAssociation(cur realm, courtSlug string, from, to uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	if c.assocOut == nil {
		panic("kourtv2: no such association")
	}
	v := c.assocOut.Get(assocKey(from, to))
	if v == nil {
		panic("kourtv2: no such association")
	}
	e := v.(*assocEdge)
	requireEdgeRemover(c, e.author, who)
	if e.bond > 0 {
		if e.author == who {
			releaseAssocBond(c, e)
		} else {
			burnAssocBond(c, e)
		}
	}
	dropAssocEdge(c, from, to)
}
func ClaimAssociations(courtSlug string, claimID uint64) string {
	c := mustCourt(courtSlug)
	mustClaim(c, claimID)
	var b strings.Builder
	b.WriteString("out:")
	if c.assocOut != nil {
		p := beClaimKey(claimID)
		n := 0
		c.assocOut.Iterate(p, "", func(key string, v any) bool {
			if !strings.HasPrefix(key, p) {
				return true
			}
			e := v.(*assocEdge)
			other := claimIDFromKey(key[8:])
			if assocTextGone(c, other) {
				return false
			}
			if n > 0 {
				b.WriteString(",")
			}
			b.WriteString(strconv.FormatUint(other, 10) + ":" + stanceCode(e.stance))
			n++
			return false
		})
	}
	b.WriteString(";in:")
	if c.assocIn != nil {
		p := beClaimKey(claimID)
		n := 0
		c.assocIn.Iterate(p, "", func(key string, v any) bool {
			if !strings.HasPrefix(key, p) {
				return true
			}
			e := v.(*assocEdge)
			other := claimIDFromKey(key[8:])
			if assocTextGone(c, other) {
				return false
			}
			if n > 0 {
				b.WriteString(",")
			}
			b.WriteString(strconv.FormatUint(other, 10) + ":" + stanceCode(e.stance))
			n++
			return false
		})
	}
	return b.String()
}
func stanceCode(s int8) string {
	if s == assocContests {
		return "c"
	}
	return "s"
}
func claimIDFromKey(k string) uint64 {
	if len(k) < 8 {
		return 0
	}
	var id uint64
	for i := 0; i < 8; i++ {
		id = id<<8 | uint64(k[i])
	}
	return id
}

package kourt
import (
	"strconv"
	"strings"
	bptree "gno.land/p/nt/bptree/v0"
	sanitize "gno.land/p/nt/markdown/sanitize/v0"
)
const (
	maxBoardTextLen = 2000
	maxBoardRowsPerClaim = 512
	maxBoardRowsPerAuthor = 8
	maxBoardRepliesShown = 8
)
type boardRow struct {
	id     uint64
	parent uint64
	author address
	text   string
	score    int64
	scoreKey string
	at int64
	hiddenByAuthor bool
	hiddenByMod    bool
	global          bool
	purged          bool
	globalClearedAt     int64
	globalClearedAtTime int64
}
func boardMark(r *boardRow) string {
	switch {
	case r.purged:
		return "x"
	case r.global:
		return "g"
	case r.hiddenByAuthor || r.hiddenByMod:
		return "h"
	}
	return "."
}
func ensureBoard(cs *claimState) {
	if cs.board == nil {
		cs.board = bptree.NewBPTree32()
		cs.boardTop = bptree.NewBPTree32()
		cs.boardWrote = bptree.NewBPTree32()
	}
}
func ensureKids(cs *claimState) *bptree.BPTree {
	if cs.boardKids == nil {
		cs.boardKids = bptree.NewBPTree32()
	}
	return cs.boardKids
}
func ensureScoreIdx(cs *claimState) *bptree.BPTree {
	if cs.boardScore == nil {
		cs.boardScore = bptree.NewBPTree32()
	}
	return cs.boardScore
}
func ensureVoted(cs *claimState) *bptree.BPTree {
	if cs.boardVoted == nil {
		cs.boardVoted = bptree.NewBPTree32()
	}
	return cs.boardVoted
}
func boardOpen(cs *claimState) bool { return cs.verdictAt == 0 && !cs.closed }
func boardWroteBy(cs *claimState, who address) int64 {
	if cs.boardWrote == nil {
		return 0
	}
	if v := cs.boardWrote.Get(string(who)); v != nil {
		return v.(int64)
	}
	return 0
}
func PostComment(cur realm, courtSlug string, claimID uint64, parentRow uint64, text string) uint64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	if courtIsPurged(c) {
		panic("kourtv2: this court is purged; it takes no new content")
	}
	cs := mustClaim(c, claimID)
	if !boardOpen(cs) {
		panic("kourtv2: this claim is settled; its board is closed to new comments")
	}
	mustBoardWritable(c, cs, who)
	text = strings.TrimSpace(text)
	if text == "" {
		panic("kourtv2: a comment needs text")
	}
	if runeLen(text) > maxBoardTextLen {
		panic("kourtv2: a comment is at most " + strconv.Itoa(maxBoardTextLen) + " characters")
	}
	if parentRow != 0 {
		p := mustBoardRow(cs, parentRow)
		if p.parent != 0 {
			panic("kourtv2: replies are one level deep; reply to the comment, not to a reply")
		}
	}
	if boardWroteBy(cs, who) >= maxBoardRowsPerAuthor {
		panic("kourtv2: you already have " + strconv.Itoa(maxBoardRowsPerAuthor) +
			" comments on this claim")
	}
	if cs.board != nil && cs.board.Size() >= maxBoardRowsPerClaim {
		panic("kourtv2: this claim's board is full")
	}
	mustSpendPost(c, who)
	ensureBoard(cs)
	cs.boardNextID++
	r := &boardRow{
		id: cs.boardNextID, parent: parentRow, author: who, text: text,
		at: heightNow(),
	}
	k := beClaimKey(r.id)
	cs.board.Set(k, r)
	if parentRow == 0 {
		cs.boardTop.Set(k, r)
		scoreIndexPut(cs, r)
	} else {
		ensureKids(cs).Set(beClaimKey(parentRow)+k, r)
	}
	cs.boardWrote.Set(string(who), boardWroteBy(cs, who)+1)
	return r.id
}
func mustBoardRow(cs *claimState, rowID uint64) *boardRow {
	if cs.board == nil {
		panic("kourtv2: no such comment")
	}
	v := cs.board.Get(beClaimKey(rowID))
	if v == nil {
		panic("kourtv2: no such comment")
	}
	return v.(*boardRow)
}
func HideOwnComment(cur realm, courtSlug string, claimID uint64, rowID uint64, hide bool) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	cs := mustClaim(mustCourt(courtSlug), claimID)
	r := mustBoardRow(cs, rowID)
	if r.author != who {
		panic("kourtv2: only a comment's author may hide their own comment")
	}
	r.hiddenByAuthor = hide
	if hide {
		scoreIndexDrop(cs, r)
	} else {
		scoreIndexPut(cs, r)
	}
}
func BoardSize(courtSlug string, claimID uint64) int {
	cs := mustClaim(mustCourt(courtSlug), claimID)
	if cs.board == nil {
		return 0
	}
	return cs.board.Size()
}
func BoardCounts(courtSlug string, ids string) string {
	c := mustCourt(courtSlug)
	out := strings.Builder{}
	sent := 0
	for _, part := range strings.Split(ids, ",") {
		if sent >= seriesPageMax {
			break
		}
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		id, err := strconv.ParseUint(part, 10, 64)
		if err != nil {
			continue
		}
		v := c.claims.Get(beClaimKey(id))
		if v == nil {
			continue
		}
		cs := v.(*claimState)
		rows, threads := 0, 0
		if cs.board != nil {
			rows = cs.board.Size()
		}
		if cs.boardTop != nil {
			threads = cs.boardTop.Size()
		}
		if sent > 0 {
			out.WriteString(";")
		}
		out.WriteString(strconv.FormatUint(id, 10))
		out.WriteString(":" + strconv.Itoa(rows))
		out.WriteString(":" + strconv.Itoa(threads))
		sent++
	}
	return out.String()
}
func BoardHiddenCount(courtSlug string, claimID uint64) int {
	cs := mustClaim(mustCourt(courtSlug), claimID)
	if cs.boardTop == nil {
		return 0
	}
	n := 0
	cs.boardTop.Iterate("", "", func(_ string, v any) bool {
		if boardMark(v.(*boardRow)) != "." {
			n++
		}
		return false
	})
	return n
}
func BoardOpen(courtSlug string, claimID uint64) bool {
	return boardOpen(mustClaim(mustCourt(courtSlug), claimID))
}
func CommentsWrittenBy(courtSlug string, claimID uint64, who address) int64 {
	return boardWroteBy(mustClaim(mustCourt(courtSlug), claimID), who)
}
func BoardNewest(courtSlug string, claimID uint64, offset, count int) string {
	cs := mustClaim(mustCourt(courtSlug), claimID)
	if cs.boardTop == nil || count <= 0 {
		return ""
	}
	if count > maxBoardRepliesShown*8 {
		count = maxBoardRepliesShown * 8
	}
	var b strings.Builder
	cs.boardTop.ReverseIterateByOffset(offset, count, func(_ string, v any) bool {
		r := v.(*boardRow)
		b.WriteString(strconv.FormatUint(r.id, 10) + "|" + r.author.String() + "|" +
			strconv.Itoa(boardReplyCount(cs, r.id)) + "|")
		if m := boardMark(r); m != "." {
			b.WriteString(m + "|" + strconv.FormatInt(r.at, 10) + "|\n")
			return false
		}
		b.WriteString(".|" + strconv.FormatInt(r.at, 10) + "|" + boardTextFor(r) + "\n")
		return false
	})
	return b.String()
}
func boardReplyCount(cs *claimState, parent uint64) int {
	if cs.boardKids == nil {
		return 0
	}
	pre := beClaimKey(parent)
	n := 0
	cs.boardKids.Iterate(pre, "", func(k string, _ any) bool {
		if !strings.HasPrefix(k, pre) || !boardKeyMine(pre, k) {
			return true
		}
		n++
		return false
	})
	return n
}
func boardKeyMine(pre, k string) bool { return len(k) == len(pre)+8 }
func BoardReplies(courtSlug string, claimID uint64, parent uint64) string {
	cs := mustClaim(mustCourt(courtSlug), claimID)
	if cs.boardKids == nil {
		return ""
	}
	pre := beClaimKey(parent)
	var b strings.Builder
	n := 0
	cs.boardKids.Iterate(pre, "", func(k string, v any) bool {
		if !strings.HasPrefix(k, pre) || !boardKeyMine(pre, k) {
			return true
		}
		r := v.(*boardRow)
		b.WriteString(strconv.FormatUint(r.id, 10) + "|" + r.author.String() + "|")
		if m := boardMark(r); m != "." {
			b.WriteString(m + "|" + strconv.FormatInt(r.at, 10) + "|\n")
		} else {
			b.WriteString(".|" + strconv.FormatInt(r.at, 10) + "|" + boardTextFor(r) + "\n")
		}
		n++
		return n >= maxBoardRepliesShown
	})
	return b.String()
}
func BoardPartyRows(courtSlug string, claimID uint64) string {
	cs := mustClaim(mustCourt(courtSlug), claimID)
	if cs.boardTop == nil {
		return ""
	}
	var b strings.Builder
	for _, r := range boardPartyRows(cs) {
		role := "answerer"
		if r.author == cs.author {
			role = "author"
		}
		b.WriteString(strconv.FormatUint(r.id, 10) + "|" + r.author.String() + "|" + role + "|")
		if m := boardMark(r); m != "." {
			b.WriteString(m + "|" + strconv.FormatInt(r.at, 10) + "|\n")
			continue
		}
		b.WriteString(".|" + strconv.FormatInt(r.at, 10) + "|" + boardTextFor(r) + "\n")
	}
	return b.String()
}
func boardTextFor(r *boardRow) string {
	if boardMark(r) != "." {
		return ""
	}
	return escapeWireText(r.text)
}
func escapeWireText(s string) string {
	if !strings.ContainsAny(s, "\\\n\r") {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		default:
			b.WriteByte(s[i])
		}
	}
	return b.String()
}
