func hideBanner(c *Court, cs *claimState) string {
	if c.mod == nil {
		return ""
	}
	clm := lookupClaimMod(c.mod, cs.id)
	if clm == nil {
		return ""
	}
	switch {
	case clm.purged:
		return "> **Removed on legal grounds** (" + sanitize.InlineText(clm.tombstone) +
			"). The claim's lifecycle is unaffected: stakes, verdict and refunds proceed.\n\n"
	case clm.global:
		return "> **Text withheld pending review.** The claim's id, its state, its deadlines and every balance are still shown, so you can always act on a position.\n\n"
	case clm.meta:
		return "> **Hidden by the review court.** Listed nowhere, reachable here; the lifecycle is unaffected.\n\n"
	case clm.court:
		return "> **Hidden by this court's moderators.** Listed nowhere, reachable here; the lifecycle is unaffected.\n\n"
	}
	return ""
}
const (
	stripHeading = "Still flaggable"
	stripBlurb   = "Answered claims that can still be flagged as spam — nearest deadline first. A claim leaves this list when its rewards are opened, not when it settles, so a settled claim stays here while it can still be flagged. This list ignores moderation: a claim hidden from the lists above still appears here."
)
func writeStrip(b *strings.Builder, slug string) {
	c := mustCourt(slug)
	n := StripSize(slug)
	if n == 0 {
		return
	}
	b.WriteString("## " + stripHeading + "\n\n" + stripBlurb + "\n\n")
	ids := StripPage(slug, 0, renderPageSize)
	for _, id := range ids {
		cs := mustClaim(c, id)
		b.WriteString("- [" + claimTitleFor(c, cs) + "](/r/g13khfsjnnq6g3lz2e997jejc9kvlz2x5yx08dr0/kourt:" + slug + "/" +
			strconv.FormatUint(id, 10) + ") — settles at block " +
			strconv.FormatInt(cs.answerHeight+settleDelay, 10) + "\n")
	}
	if n > len(ids) {
		b.WriteString("- _…and " + strconv.Itoa(n-len(ids)) + " more_\n")
	}
	b.WriteString("\n")
}
func writePending(b *strings.Builder, slug string) {
	c := mustCourt(slug)
	n := PendingSize(slug)
	if n == 0 {
		return
	}
	b.WriteString("## Awaiting an answer\n\nSeeded and appeal claims that no one has answered yet.\n\n")
	ids := PendingPage(slug, 0, renderPageSize)
	for _, id := range ids {
		cs := mustClaim(c, id)
		tag := ""
		if cs.seeded {
			tag = " — seeded by a moderator"
		}
		b.WriteString("- [" + claimTitleFor(c, cs) + "](/r/g13khfsjnnq6g3lz2e997jejc9kvlz2x5yx08dr0/kourt:" + slug + "/" +
			strconv.FormatUint(id, 10) + ")" + tag + "\n")
	}
	if n > len(ids) {
		b.WriteString("- _…and " + strconv.Itoa(n-len(ids)) + " more_\n")
	}
	b.WriteString("\n")
}
func writeAppeal(b *strings.Builder, c *Court, cs *claimState) {
	if c.id != metaSlug {
		return
	}
	verb, court, target, valid := AppealParse(cs.id)
	if !valid {
		b.WriteString("> _Not a valid review request — this is an ordinary claim on the review court._\n\n")
		return
	}
	b.WriteString("## Review request\n\n")
	b.WriteString("- action: **" + sanitize.InlineText(verb) + "** — " +
		appealVerbGloss(verb) + "\n")
	b.WriteString("- court: " + sanitize.InlineText(court) + "\n")
	if verbIsAggressive(verb) {
		b.WriteString("- this is an **aggressive** act: it can only carry on a " +
			"contested vote that real opposition turned out for. Silence " +
			"defeats it.\n")
	} else {
		b.WriteString("- this is a **restorative** act: it undoes a restriction, so " +
			"it can carry undisputed. Silence lets it through.\n")
	}
	if verb == verbSetmods {
		b.WriteString("- installs candidate set #" + strconv.FormatUint(target, 10) + ":\n")
		if !Exists(court) {
			b.WriteString("  - _that court does not exist_\n\n")
			return
		}
		tc := mustCourt(court)
		if tc.mod == nil || tc.mod.candidates == nil ||
			tc.mod.candidates.Get(beClaimKey(target)) == nil {
			b.WriteString("  - **this candidate set does not exist yet — do not approve**\n\n")
			return
		}
		cand := tc.mod.candidates.Get(beClaimKey(target)).(*modCandidate)
		for _, a := range cand.members {
			b.WriteString("  - " + sanitize.InlineText(a.String()) + "\n")
		}
		b.WriteString("  - threshold: " + strconv.Itoa(cand.m) + " of " +
			strconv.Itoa(len(cand.members)) + " must agree\n")
	} else if target != 0 {
		b.WriteString("- claim: " + strconv.FormatUint(target, 10) + "\n")
	}
	b.WriteString("\n")
}
func modActLine(a modAct, kind string) string {
	line := "- " + kind + " " + strconv.FormatUint(a.rowID, 10) +
		" · block " + strconv.FormatInt(a.height, 10) + " · " +
		sanitize.InlineText(a.code) + " · by " + sanitize.InlineText(a.actor.String())
	switch {
	case a.purged:
		line += " — _[reason removed on legal grounds]_"
	case a.reason != "":
		line += " — " + sanitize.InlineText(a.reason)
	}
	return line
}
func renderModLog(slug string) string {
	if !Exists(slug) {
		return "## Not found\nNo court by that slug."
	}
	c := mustCourt(slug)
	b := strings.Builder{}
	b.WriteString("# Moderation log — " + courtNameFor(c) + "\n\n")
	b.WriteString("Every moderation act on this court's CLAIMS and COMMENTS is recorded here: who acted, what they did, and when. Moderation controls what is listed; it never moves a coin or changes a verdict.\n\n")
	b.WriteString("[Who holds these seats, and how to challenge them](/r/g13khfsjnnq6g3lz2e997jejc9kvlz2x5yx08dr0/kourt:" +
		sanitize.InlineText(slug) + "/election)\n\n")
	b.WriteString("Curation — which claims a moderator filed under which heading — is " +
		"not in this list. The tree it produced is on the [court page](/r/g13khfsjnnq6g3lz2e997jejc9kvlz2x5yx08dr0/kourt:" + sanitize.InlineText(slug) + "); the acts themselves are in " +
		"the chain's event stream.\n\n")
	if c.mod == nil {
		b.WriteString("## Moderators\n\n1-of-1 — " + c.admin.String() +
			" (the court's creator, until an election or an appointment changes it)\n\n")
		b.WriteString("_No moderation acts yet._\n")
		return b.String()
	}
	cm := c.mod
	if cm.courtPurged {
		b.WriteString("> **This court was removed on legal grounds** (" +
			sanitize.InlineText(cm.courtTombstone) + "). No new claims may be opened; existing claims settle and pay out normally.\n\n")
	}
	b.WriteString("## Moderators\n\n")
	if cm.n == 0 {
		b.WriteString("_None — the set is empty; the court's holders can elect one._\n\n")
	} else {
		b.WriteString("- " + strconv.Itoa(cm.m) + " of " + strconv.Itoa(cm.n) +
			" must agree for a moderation act\n")
		if sm := speechM(cm); sm != cm.m {
			b.WriteString("- " + strconv.Itoa(sm) + " of " + strconv.Itoa(cm.n) +
				" for a **board** act — hiding a comment, slashing standing, " +
				"freezing an address — because speech takes a wider agreement " +
				"than the set's own threshold\n")
		}
		if cm.suspended {
			b.WriteString("- **suspended** — they cannot take new moderation acts. " +
				"The hides and freezes already in place stand until cleared, and " +
				"any member may still lift their own\n")
		}
		if cm.installedByMeta {
			b.WriteString("- seated by the review court; may not seed claims until a local election\n")
		}
		b.WriteString("\n")
	}
	pendingRows := []string{}
	pendingSeen := 0
	pendingMore := false
	cm.pending.Iterate("", "", func(key string, v any) bool {
		pendingSeen++
		if a, ok := v.(*approval); ok {
			deadline := a.openedAt + pendingTTLBlocks
			if !approvalStale(a) {
				when := " (block " + strconv.FormatInt(deadline, 10) + ")"
				if at := deadlineTime(a.openedAtTime, blocksToSecs(pendingTTLBlocks)); at != 0 {
					when = " " + strconv.FormatInt(at, 10) + when
				}
				pendingRows = append(pendingRows,
					"- "+sanitize.InlineCode(key)+" — "+strconv.Itoa(a.approvers.Size())+
						" of "+strconv.Itoa(cm.m)+" approved, expires at"+when)
			}
		}
		if len(pendingRows) >= renderPageSize || pendingSeen >= renderPageSize {
			pendingMore = true
			return true
		}
		return false
	})
	if len(pendingRows) > 0 {
		b.WriteString("## Awaiting approval\n\nProposals this set has started and not yet carried. An approval expires if the set does not reach its threshold in time; the reason is withheld until the act carries.\n\n")
		for _, r := range pendingRows {
			b.WriteString(r + "\n")
		}
		if pendingMore {
			b.WriteString("- _…more not shown_\n")
		}
		b.WriteString("\n")
	}
	rows := []string{}
	visited := 0
	truncated := false
	for i := len(cm.log) - 1; i >= 0 && len(rows) < renderPageSize; i-- {
		rows = append(rows, modActLine(cm.log[i], "court row"))
	}
	if len(rows) >= renderPageSize {
		truncated = true
	}
	cm.claims.ReverseIterate("", "", func(_ string, v any) bool {
		if len(rows) >= renderPageSize {
			truncated = true
			return true
		}
		clm, ok := v.(*claimMod)
		if !ok {
			return false
		}
		visited++
		for i := len(clm.log) - 1; i >= 0; i-- {
			rows = append(rows, modActLine(clm.log[i], "row"))
			if len(rows) >= renderPageSize {
				truncated = true
				return true
			}
		}
		if visited >= renderPageSize {
			truncated = true
			return true
		}
		return false
	})
	b.WriteString("## Acts\n\n")
	if len(rows) == 0 {
		b.WriteString("_No moderation acts yet._\n")
		return b.String()
	}
	for _, r := range rows {
		b.WriteString(r + "\n")
	}
	if truncated {
		b.WriteString("\n_Showing the " + strconv.Itoa(len(rows)) +
			" most recent acts. This court has moderated " + strconv.Itoa(cm.claims.Size()) +
			" claims; older acts are not shown._\n")
	}
	return b.String()
}
func appealVerbGloss(verb string) string {
	switch verb {
	case verbUnhide:
		return "un-hides a claim its own court's moderators hid"
	case verbClear:
		return "clears a hide the review court itself placed"
	case verbHide:
		return "hides a claim across the platform, over its court's head"
	case verbSuspend:
		return "disarms a court's moderator set — they can take no further act"
	case verbUnsuspend:
		return "re-arms a suspended moderator set, and re-applies the hides that " +
			"were masked while it was disarmed"
	case verbSetmods:
		return "installs a moderator set on that court, replacing whoever holds " +
			"the seats now"
	}
	return "an action this page does not recognise"
}

package kourt
import (
	"chain"
	"strconv"
	grc20votes "gno.land/p/g13khfsjnnq6g3lz2e997jejc9kvlz2x5yx08dr0/grc20votes/v0"
	bptree "gno.land/p/nt/bptree/v0"
)
const (
	nominationWindow = int64(17_280)
	maxBallotLines = 64
	electionBondBps = int64(50)
)
func mustElectionInvariants() {
	if electionBondBps <= 0 {
		panic("kourtv2: the election bond must be positive")
	}
	if electionBondBps >= quorumSupplyBps {
		panic("kourtv2: the election bond must stay below the quorum floor — else affording the ballot is harder than winning the vote (incumbency lock by price)")
	}
	if nominationWindow < 17_280 {
		panic("kourtv2: the nomination window must be at least a day")
	}
}
func init() { mustElectionInvariants() }
type modCandidate struct {
	id      uint64
	members []address
	m       int
	by      address
	at      int64
}
type ballotLine struct {
	candID uint64
	weight int64
	nomAt  int64
	bond   int64
	poster address
}
type election struct {
	seq         uint64
	epoch       uint32
	openedAt    int64
	nominateEnd int64
	voteEnd     int64
	nominateEndTime int64
	voteEndTime     int64
	floor       int64
	bond        int64
	lines       *bptree.BPTree
	retainW     int64
	nominators  *bptree.BPTree
	voters      *bptree.BPTree
	approvals   *bptree.BPTree
	turnout     int64
	resolved    bool
}
func electionFloor(c *Court, at uint32) int64 {
	f := mulDiv128(votableAt(c, at), quorumSupplyBps, grc20votes.Bps)
	if f < 1 {
		f = 1
	}
	return f
}
func votableAt(c *Court, at uint32) int64 {
	v := c.coin.PastTotal(at) - c.coin.PastVotes(c.escrow, at)
	if v < 0 {
		v = 0
	}
	return v
}
func electionBond(c *Court, at uint32) int64 {
	b := mulDiv128(votableAt(c, at), electionBondBps, grc20votes.Bps)
	if b < carrotClampMinCC {
		b = carrotClampMinCC
	}
	if f := electionFloor(c, at); b > f {
		b = f
	}
	return b
}
func RegisterModCandidate(cur realm, courtSlug string, m int, members ...address) uint64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := ensureMod(c)
	canon := canonicalMembers(members)
	if len(canon) == 0 {
		panic("kourtv2: a candidate set may not be empty")
	}
	if m < 1 || m > len(canon) {
		panic("kourtv2: the m-of-n threshold must be in 1..n")
	}
	if cm.candidates == nil {
		cm.candidates = bptree.NewBPTree32()
	}
	cm.candSeq++
	id := cm.candSeq
	cm.candidates.Set(beClaimKey(id), &modCandidate{
		id: id, members: canon, m: m, by: who, at: heightNow(),
	})
	return id
}
func canonicalMembers(in []address) []address {
	if len(in) > maxModSetSize {
		panic("kourtv2: a moderator set is at most 32 members")
	}
	out := []address{}
	for _, a := range in {
		if a == "" {
			panic("kourtv2: a moderator address may not be zero")
		}
		if !a.IsValid() {
			panic("kourtv2: not a valid address for a moderator set")
		}
		dup := false
		for _, b := range out {
			if b == a {
				dup = true
				break
			}
		}
		if dup {
			continue
		}
		pos := len(out)
		out = append(out, a)
		for pos > 0 && out[pos-1].String() > a.String() {
			out[pos] = out[pos-1]
			pos--
		}
		out[pos] = a
	}
	return out
}
func (cm *courtMod) mustCandidate(id uint64) *modCandidate {
	if cm.candidates == nil {
		panic("kourtv2: no such candidate")
	}
	v := cm.candidates.Get(beClaimKey(id))
	if v == nil {
		panic("kourtv2: no such candidate")
	}
	return v.(*modCandidate)
}
func electionCooldownOpen(cm *courtMod) bool {
	passed, known := pastDeadline(cm.electionCooldownUntilTime, 0)
	return (known && !passed) || (!known && heightNow() < cm.electionCooldownUntil)
}
func nominationClosed(e *election) bool {
	passed, known := pastDeadline(e.nominateEndTime, 0)
	return (known && passed) || (!known && heightNow() >= e.nominateEnd)
}
func votingClosed(e *election) bool {
	passed, known := pastDeadline(e.voteEndTime, 0)
	return (known && passed) || (!known && heightNow() >= e.voteEnd)
}
func OpenElection(cur realm, courtSlug string, candidateID uint64) uint64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := ensureMod(c)
	if cm.election != nil && !cm.election.resolved {
		panic("kourtv2: an election is already open for this court")
	}
	now := heightNow()
	if electionCooldownOpen(cm) {
		panic("kourtv2: this court is in its post-election cooldown")
	}
	cand := cm.mustCandidate(candidateID)
	at := c.coin.Epoch() - 1
	cm.electionSeq++
	e := &election{
		seq:         cm.electionSeq,
		epoch:       at,
		openedAt:    now,
		nominateEnd: now + nominationWindow,
		voteEnd:     now + nominationWindow + c.params.votingBlocks,
		nominateEndTime: nowTime() + blocksToSecs(nominationWindow),
		voteEndTime:     nowTime() + blocksToSecs(nominationWindow+c.params.votingBlocks),
		floor:       electionFloor(c, at),
		bond:        electionBond(c, at),
		lines:       bptree.NewBPTree32(),
		nominators:  bptree.NewBPTree32(),
		voters:      bptree.NewBPTree32(),
		approvals:   bptree.NewBPTree32(),
	}
	cm.election = e
	addNomination(c, cm, e, cand, who)
	return e.seq
}
func NominateCandidate(cur realm, courtSlug string, candidateID uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := ensureMod(c)
	e := cm.mustOpenElection()
	if nominationClosed(e) {
		panic("kourtv2: the nomination window has closed")
	}
	cand := cm.mustCandidate(candidateID)
	addNomination(c, cm, e, cand, who)
}
func addNomination(c *Court, cm *courtMod, e *election, cand *modCandidate, who address) {
	if e.lines.Size() >= maxBallotLines {
		panic("kourtv2: this ballot is full; open the next election instead")
	}
	if e.nominators.Has(who.String()) {
		panic("kourtv2: one nomination per address per election")
	}
	if e.lines.Has(beClaimKey(cand.id)) {
		panic("kourtv2: that candidate is already on the ballot")
	}
	mustSpendable(c, who, e.bond)
	c.coin.Transfer(who, c.escrow, e.bond)
	e.nominators.Set(who.String(), true)
	e.lines.Set(beClaimKey(cand.id), &ballotLine{
		candID: cand.id, nomAt: heightNow(), bond: e.bond, poster: who,
	})
}
func (cm *courtMod) mustOpenElection() *election {
	if cm.election == nil || cm.election.resolved {
		panic("kourtv2: no election is open")
	}
	return cm.election
}
func ApproveCandidate(cur realm, courtSlug string, candidateID uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	approve(cur.Previous().Address(), courtSlug, candidateID, false)
}
func ApproveRetain(cur realm, courtSlug string) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	approve(cur.Previous().Address(), courtSlug, 0, true)
}
func approve(who address, courtSlug string, candidateID uint64, retain bool) {
	c := mustCourt(courtSlug)
	cm := ensureMod(c)
	e := cm.mustOpenElection()
	if !nominationClosed(e) {
		panic("kourtv2: voting opens when the nomination window closes")
	}
	if votingClosed(e) {
		panic("kourtv2: voting has closed")
	}
	var w int64
	if prior := e.voters.Get(who.String()); prior != nil {
		w = prior.(int64)
	} else {
		var snapshot int64
		w, snapshot = votingWeight(c, who, e.epoch)
		if snapshot <= 0 {
			panic("kourtv2: no voting weight at the pinned epoch")
		}
		if w <= 0 {
			panic("kourtv2: you no longer hold the coin you would vote with")
		}
	}
	key := beClaimKey(candidateID) + who.String()
	if retain {
		key = "retain" + who.String()
	}
	if e.approvals.Has(key) {
		panic("kourtv2: already approved that line")
	}
	if !retain {
		v := e.lines.Get(beClaimKey(candidateID))
		if v == nil {
			panic("kourtv2: that candidate is not on the ballot")
		}
		line := v.(*ballotLine)
		line.weight += w
	} else {
		e.retainW += w
	}
	e.approvals.Set(key, true)
	if !e.voters.Has(who.String()) {
		e.voters.Set(who.String(), w)
		e.turnout += w
		lockVote(c, who, voteLockElection, int64(e.seq), 0, w)
	}
}
func ResolveElection(cur realm, courtSlug string) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	c := mustCourt(courtSlug)
	cm := ensureMod(c)
	e := cm.mustOpenElection()
	now := heightNow()
	if !votingClosed(e) {
		panic("kourtv2: the voting window has not closed")
	}
	e.resolved = true
	maxW := int64(0)
	e.lines.Iterate("", "", func(_ string, v any) bool {
		if l, ok := v.(*ballotLine); ok && l.weight > maxW {
			maxW = l.weight
		}
		return false
	})
	install := maxW > 0 && e.turnout >= e.floor && maxW-e.retainW >= e.floor
	var winner *ballotLine
	if install {
		e.lines.Iterate("", "", func(_ string, v any) bool {
			l, ok := v.(*ballotLine)
			if !ok || l.weight < maxW-e.floor || l.weight-e.retainW < e.floor {
				return false
			}
			if winner == nil || l.nomAt < winner.nomAt ||
				(l.nomAt == winner.nomAt && l.candID < winner.candID) {
				winner = l
			}
			return false
		})
	}
	e.lines.Iterate("", "", func(_ string, v any) bool {
		l, ok := v.(*ballotLine)
		if !ok || l.bond <= 0 {
			return false
		}
		if winner != nil && l.candID == winner.candID {
			c.coin.Transfer(c.escrow, l.poster, l.bond)
		} else {
			half := l.bond / 2
			if half > 0 {
				c.coin.Transfer(c.escrow, l.poster, half)
			}
			if burn := l.bond - half; burn > 0 {
				c.coin.Burn(c.escrow, burn)
			}
		}
		l.bond = 0
		return false
	})
	if winner != nil {
		cand := cm.mustCandidate(winner.candID)
		installModSet(c, cm, cand, now, true)
		chain.Emit("ModSetInstalled",
			"court", c.id, "by", "election",
			"candidate", strconv.FormatUint(cand.id, 10),
			"height", strconv.FormatInt(now, 10),
		)
		return
	}
	cm.electionCooldownUntil = now + decideWindowBlocks
	cm.electionCooldownUntilTime = nowTime() + blocksToSecs(decideWindowBlocks)
}
func installModSet(c *Court, cm *courtMod, cand *modCandidate, at int64, byElection bool) {
	fresh := bptree.NewBPTree32()
	for _, a := range cand.members {
		fresh.Set(a.String(), true)
	}
	cm.members = fresh
	cm.n = len(cand.members)
	cm.m = cand.m
	clearPendingOnMembershipChange(&cm.pending)
	cm.setActHeight = at
	cm.installedByMeta = !byElection
	if currentSetID(cm) != cm.suspendedSetID || cm.m > cm.suspendedM {
		cm.suspended = false
		cm.suspendedSetID = ""
		cm.suspendedM = 0
	}
	if byElection {
		cm.lastElectionAt = at
		cm.creatorUnseated = true
	}
}
func mustModRead(courtSlug string) *courtMod {
	c := mustCourt(courtSlug)
	if c.mod == nil {
		panic("kourtv2: this court has no moderation state yet")
	}
	return c.mod
}
func ElectionOpen(courtSlug string) bool {
	c := mustCourt(courtSlug)
	return c.mod != nil && c.mod.election != nil && !c.mod.election.resolved
}
func ElectionWindows(courtSlug string) (int64, int64) {
	e := mustModRead(courtSlug).mustOpenElection()
	return e.nominateEnd, e.voteEnd
}
func ElectionFloorOf(courtSlug string) int64 {
	return mustModRead(courtSlug).mustOpenElection().floor
}
func ElectionBondOf(courtSlug string) int64 {
	return mustModRead(courtSlug).mustOpenElection().bond
}
func ElectionTally(courtSlug string, candidateID uint64) (candW, retainW, turnout int64) {
	e := mustModRead(courtSlug).mustOpenElection()
	if v := e.lines.Get(beClaimKey(candidateID)); v != nil {
		candW = v.(*ballotLine).weight
	}
	return candW, e.retainW, e.turnout
}
func CandidateMembers(courtSlug string, candidateID uint64) []address {
	cand := mustModRead(courtSlug).mustCandidate(candidateID)
	out := make([]address, len(cand.members))
	copy(out, cand.members)
	return out
}
func CandidateThreshold(courtSlug string, candidateID uint64) int {
	return mustModRead(courtSlug).mustCandidate(candidateID).m
}
func ElectionCooldownUntil(courtSlug string) int64 {
	c := mustCourt(courtSlug)
	if c.mod == nil {
		return 0
	}
	return c.mod.electionCooldownUntil
}

package kourt
import (
	"math/bits"
)
func OpenRewards(cur realm, courtSlug string, claimID uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if cs.rewardsOpened {
		panic("kourtv2: already rewardsOpened")
	}
	if cs.verdictAt == 0 {
		panic("kourtv2: no final verdict yet")
	}
	if cs.closed {
		panic("kourtv2: dead claims have no draw")
	}
	now := heightNow()
	if passed, known := pastDeadline(cs.verdictAtTime, finalizeGraceSecs); ((known && !passed) ||
		(!known && now < cs.verdictAt+finalizeGraceBlocks)) && !isParticipant(cs, who) {
		panic("kourtv2: OpenRewards is participant-only for its first week")
	}
	touch(c)
	advancePools(c, cs)
	cs.rewardsOpened = true
	stripExit(c, cs)
	releaseMetaLatchIfMeta(c, cs)
	cs.openBlocks = cs.frozenAt - (cs.openedAt + c.params.stakeOpenDelayBlocks)
	if cs.openBlocks < 1 {
		cs.openBlocks = 1
	}
	var midGross int64
	if int(cs.provisional) == sideYES {
		midGross = convToCC(cs.yesConvHi, cs.yesConvLo)
	} else {
		midGross = convToCC(cs.noConvHi, cs.noConvLo)
	}
	cs.winPoolConvCC = midGross
	want := drawWant(c, cs, midGross)
	d := reserveJunior(c, want)
	cs.drawWinners, cs.drawAuthor, cs.drawAnswerer = drawSplit(cs, d)
	cs.carrotTotal = mulDiv128(midGross, splitCarrot, 100)
	cs.carrotPool = cs.carrotTotal
	if cs.deposit > 0 {
		c.coin.Transfer(c.escrow, cs.author, cs.deposit)
		c.deposit -= cs.deposit
		cs.deposit = 0
	}
	if cs.fee > 0 {
		c.coin.Transfer(c.escrow, cs.author, cs.fee)
		c.deposit -= cs.fee
		cs.fee = 0
	}
	if cs.answerBond > 0 {
		settleAnswerBond(c, cs)
	}
}
func WithdrawBonus(cur realm, courtSlug string, claimID uint64, side int) int64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	mustSide(side)
	if !cs.rewardsOpened {
		panic("kourtv2: the draw has not rewardsOpened")
	}
	if side != int(cs.provisional) {
		panic("kourtv2: only the winning side draws (principal came back either way)")
	}
	v := cs.stakers.Get(posKey(who, side))
	if v == nil {
		panic("kourtv2: no position on that side")
	}
	p := v.(*stakePos)
	if p.bonusPaid {
		panic("kourtv2: this position's bonus was already drawn")
	}
	touch(c)
	accrue(c, cs, p, side)
	p.bonusPaid = true
	convCC := convToCC(p.convHi, p.convLo)
	creditWinConviction(c, cs, who, p)
	if convCC <= 0 || cs.winPoolConvCC <= 0 {
		return 0
	}
	gross := mulDiv128(cs.drawWinners, convCC, cs.winPoolConvCC)
	pay := capBonus(cs, gross, p.rawHi, p.rawLo)
	mintEmission(c, who, pay)
	return pay
}
func AuthorBonus(cur realm, courtSlug string, claimID uint64) int64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if !cs.rewardsOpened {
		panic("kourtv2: the draw has not rewardsOpened")
	}
	if who != cs.author {
		panic("kourtv2: only the author draws this slice")
	}
	if cs.authorPaid {
		panic("kourtv2: the author slice was already drawn")
	}
	touch(c)
	cs.authorPaid = true
	var pay int64
	if cs.seeded {
		mintEmission(c, who, 0)
		return 0
	}
	if v := cs.stakers.Get(posKey(who, int(cs.provisional))); v != nil {
		p := v.(*stakePos)
		accrue(c, cs, p, int(cs.provisional))
		pay = capBonus(cs, cs.drawAuthor, p.rawHi, p.rawLo)
	}
	mintEmission(c, who, pay)
	return pay
}
func AnswererBonus(cur realm, courtSlug string, claimID uint64) int64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if !cs.rewardsOpened {
		panic("kourtv2: the draw has not rewardsOpened")
	}
	if who != cs.answerer {
		panic("kourtv2: only the answerer draws this slice")
	}
	if cs.answererPaid {
		panic("kourtv2: the answerer slice was already drawn")
	}
	touch(c)
	cs.answererPaid = true
	pay := cs.drawAnswerer
	if bound := mulDiv128(cs.answerBond0, tierBpsFor(cs), 2*tierParBps); pay > bound {
		pay = bound
	}
	mintEmission(c, who, pay)
	return pay
}
func timeAvgStake(cs *claimState, rawHi, rawLo uint64) int64 {
	if cs.openBlocks <= 0 || rawHi >= uint64(cs.openBlocks) {
		return 0
	}
	return div128(rawHi, rawLo, cs.openBlocks)
}
func capBonus(cs *claimState, gross int64, rawHi, rawLo uint64) int64 {
	rawAvg := timeAvgStake(cs, rawHi, rawLo)
	bound := mulDiv128(rawAvg, tierBpsFor(cs), 2*tierParBps)
	if gross > bound {
		gross = bound
	}
	if gross < 0 {
		gross = 0
	}
	return gross
}
func PullCarrot(cur realm, courtSlug string, claimID uint64) int64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if !cs.rewardsOpened {
		panic("kourtv2: the draw has not rewardsOpened")
	}
	if isParticipant(cs, who) {
		panic("kourtv2: participants take their own slices, never the carrot")
	}
	if cs.voted == nil {
		panic("kourtv2: nobody voted on this claim")
	}
	if cs.decidedPID == 0 {
		panic("kourtv2: no vote resolved this claim; there is no carrot")
	}
	v := cs.voted.Get("d" + beClaimKey(uint64(cs.decidedPID)) + string(who))
	if v == nil || v.(string) != cs.carrotChoice {
		panic("kourtv2: the carrot pays with-verdict voters of the deciding round")
	}
	vw := cs.voted.Get("dw" + beClaimKey(uint64(cs.decidedPID)) + string(who))
	if vw == nil {
		panic("kourtv2: no recorded weight for that voter on the deciding round")
	}
	w, denom := vw.(int64), cs.carrotDenom
	claimedKey := "c" + beClaimKey(uint64(cs.decidedPID)) + string(who)
	if cs.voted.Has(claimedKey) {
		panic("kourtv2: carrot already claimed")
	}
	cs.voted.Set(claimedKey, true)
	if w <= 0 || denom <= 0 {
		return 0
	}
	touch(c)
	share := mulDiv128(cs.carrotTotal, w, denom)
	b0 := cs.xBarFrozen * carrotClampXBps / 10000
	if b0 < carrotClampMinCC {
		b0 = carrotClampMinCC
	}
	if clamp := b0/2 - 1; share > clamp {
		share = clamp
	}
	if share > cs.carrotPool {
		share = cs.carrotPool
	}
	if share <= 0 {
		return 0
	}
	cs.carrotPool -= share
	enqueueSenior(c, who, share, "carrot")
	return share
}
func div128(hi, lo uint64, den int64) int64 {
	if den <= 0 {
		panic("kourtv2: div128 domain")
	}
	if hi >= uint64(den) {
		panic("kourtv2: div128 quotient overflow")
	}
	q, _ := bits.Div64(hi, lo, uint64(den))
	return int64(q)
}
func RewardsOpened(courtSlug string, claimID uint64) bool {
	return mustClaim(mustCourt(courtSlug), claimID).rewardsOpened
}
func drawEntitlement(c *Court, cs *claimState, midGross int64) int64 {
	tierBps := tierBpsFor(cs)
	want := mulDiv128(midGross, tierBps, tierParBps)
	want = mulDiv128(want, spamNetBps(cs), tierParBps)
	if int(cs.provisional) == int(cs.answer) {
		if capd := cs.answerBond0 - mulDiv128(midGross, splitCarrot, 100); want > capd {
			want = capd
			if want < 0 {
				want = 0
			}
		}
	}
	return want
}
func drawWant(c *Court, cs *claimState, midGross int64) int64 {
	want := drawEntitlement(c, cs, midGross)
	if want > c.curPeriodBudget {
		want = c.curPeriodBudget
	}
	return want
}
func drawSplit(cs *claimState, d int64) (winners, author, answerer int64) {
	winners = d * splitWinners / (splitWinners + splitAuthor + splitAnswerer)
	author = d * splitAuthor / (splitWinners + splitAuthor + splitAnswerer)
	answerer = d * splitAnswerer / (splitWinners + splitAuthor + splitAnswerer)
	if int(cs.provisional) != int(cs.answer) {
		answerer = 0
	}
	if cs.seeded {
		author = 0
	}
	if cs.noAccuracy {
		winners = 0
	}
	return winners, author, answerer
}
func DrawQuote(courtSlug string, claimID uint64) (winners, author, answerer int64) {
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if cs.verdictAt == 0 || cs.rewardsOpened || cs.provisional < 0 {
		return 0, 0, 0
	}
	var midGross int64
	if cs.provisional == sideYES {
		midGross = convToCC(cs.yesConvHi, cs.yesConvLo)
	} else {
		midGross = convToCC(cs.noConvHi, cs.noConvLo)
	}
	return drawSplit(cs, drawEntitlement(c, cs, midGross))
}
func DrawSlices(courtSlug string, claimID uint64) (winners, author, answerer, carrotLeft int64) {
	cs := mustClaim(mustCourt(courtSlug), claimID)
	return cs.drawWinners, cs.drawAuthor, cs.drawAnswerer, cs.carrotPool
}
func PullState(courtSlug string, claimID uint64, who address) (winnerPaid, authorPaid, answererPaid bool) {
	cs := mustClaim(mustCourt(courtSlug), claimID)
	if cs.provisional >= 0 {
		if v := cs.stakers.Get(posKey(who, int(cs.provisional))); v != nil {
			winnerPaid = v.(*stakePos).bonusPaid
		}
	}
	return winnerPaid, cs.authorPaid && who == cs.author, cs.answererPaid && who == cs.answerer
}

package kourt
import (
	"chain"
	"strconv"
	"strings"
	sanitize "gno.land/p/nt/markdown/sanitize/v0"
)
const (
	ladderT1BpsInit = int64(5)
	ladderT2BpsInit = int64(25)
	ladderT3BpsInit = int64(100)
	postsEntryInit = int64(3)
	postsT2Init    = int64(10)
	postsT3Init    = int64(30)
	ladderTopRatio = int64(10)
	passPriceMinCC = int64(100_000)
	passPriceBps   = int64(1)
	passPriceOfT3 = int64(100)
)
func mustPostingInvariants() {
	if postsT3Init != postsEntryInit*ladderTopRatio {
		panic("kourtv2: the top rung must be exactly ladderTopRatio x entry — the ratio is the bound, not a suggestion")
	}
	if !(0 < ladderT1BpsInit && ladderT1BpsInit < ladderT2BpsInit && ladderT2BpsInit < ladderT3BpsInit) {
		panic("kourtv2: the ladder must be strictly increasing")
	}
	if !(0 < postsEntryInit && postsEntryInit < postsT2Init && postsT2Init < postsT3Init) {
		panic("kourtv2: the rates must be strictly increasing")
	}
	if ladderT3BpsInit < passPriceOfT3*passPriceBps {
		panic("kourtv2: t3 must be at least 100x the pass price, or a unit of standing is worth more than the flag lane's burn can cover")
	}
}
func init() { mustPostingInvariants() }
type ladder struct {
	t1Bps, t2Bps, t3Bps int64
	postsEntry, postsT2 int64
}
var ladderDefault = ladder{
	t1Bps: ladderT1BpsInit, t2Bps: ladderT2BpsInit, t3Bps: ladderT3BpsInit,
	postsEntry: postsEntryInit, postsT2: postsT2Init,
}
func (l ladder) postsT3() int64 { return l.postsEntry * ladderTopRatio }
func ladderFor(c *Court) ladder {
	if c.ladder != nil {
		return *c.ladder
	}
	return ladderDefault
}
func mustLadder(l ladder) {
	if !(0 < l.t1Bps && l.t1Bps < l.t2Bps && l.t2Bps < l.t3Bps && l.t3Bps <= 10_000) {
		panic("kourtv2: the ladder must be strictly increasing within 0..10000 bps")
	}
	if !(0 < l.postsEntry && l.postsEntry < l.postsT2 && l.postsT2 < l.postsT3()) {
		panic("kourtv2: the posting rates must be strictly increasing")
	}
	if l.t3Bps < passPriceOfT3*passPriceBps {
		panic("kourtv2: t3 must stay at least 100x the pass price — lowering it alone would make a unit of standing worth more than the flag lane's burn can cover")
	}
}
func SetLadderDefault(cur realm, t1Bps, t2Bps, t3Bps, postsEntry, postsT2 int64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	d := ensureGlobalDAO()
	if cur.Previous().Address() != d.admin {
		panic("kourtv2: only the global DAO admin sets the default ladder")
	}
	l := ladder{t1Bps, t2Bps, t3Bps, postsEntry, postsT2}
	mustLadder(l)
	ladderDefault = l
	chain.Emit(globalActEvent,
		"court", "*",
		"claim", "0",
		"act", "set-ladder-default:"+ladderKey(l),
		"by", cur.Previous().Address().String(),
		"height", eventHeight(),
	)
}
func SetCourtLadder(cur realm, courtSlug string, t1Bps, t2Bps, t3Bps, postsEntry, postsT2 int64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := ensureMod(c)
	requireActiveMod(cm, who)
	l := ladder{t1Bps, t2Bps, t3Bps, postsEntry, postsT2}
	mustLadder(l)
	if fire, _ := approveAction(cm.pending, "setladder:"+ladderKey(l), who, "",
		speechM(cm)); !fire {
		return
	}
	c.ladder = &l
	cm.appendCourtLog(who, "setladder:"+ladderKey(l), "")
	emitModAct(c.id, 0, "setladder", who)
}
func ladderKey(l ladder) string {
	return strconv.FormatInt(l.t1Bps, 10) + ":" + strconv.FormatInt(l.t2Bps, 10) +
		":" + strconv.FormatInt(l.t3Bps, 10) + ":" +
		strconv.FormatInt(l.postsEntry, 10) + ":" + strconv.FormatInt(l.postsT2, 10)
}
func ClearCourtLadder(cur realm, courtSlug string) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := ensureMod(c)
	requireMod(cm, who)
	if c.ladder == nil {
		panic("kourtv2: this court has no ladder override")
	}
	if fire, _ := approveAction(cm.pending, "clearladder:"+c.id, who, "",
		speechM(cm)); !fire {
		return
	}
	c.ladder = nil
	cm.appendCourtLog(who, "clearladder", "")
	emitModAct(c.id, 0, "clearladder", who)
}
func boardSupply(c *Court) (int64, bool) {
	if c.coin.Epoch() < 2 {
		return 0, false
	}
	return c.coin.PastTotal(c.coin.Epoch() - 1), true
}
func passPriceFor(c *Court) int64 {
	sup, sealed := boardSupply(c)
	if !sealed {
		return 0
	}
	p := sup * passPriceBps / 10_000
	if p < passPriceMinCC {
		p = passPriceMinCC
	}
	if lid := sup * ladderFor(c).t3Bps / 10_000 / passPriceOfT3; p > lid {
		p = lid
	}
	if p < 0 {
		p = 0
	}
	return p
}
func PassPrice(courtSlug string) int64 { return passPriceFor(mustCourt(courtSlug)) }
func Ladder(courtSlug string) string {
	c := mustCourt(courtSlug)
	l := ladderFor(c)
	inherited := "1"
	if c.ladder != nil {
		inherited = "0"
	}
	return "t1:" + strconv.FormatInt(l.t1Bps, 10) +
		";t2:" + strconv.FormatInt(l.t2Bps, 10) +
		";t3:" + strconv.FormatInt(l.t3Bps, 10) +
		";entry:" + strconv.FormatInt(l.postsEntry, 10) +
		";l2:" + strconv.FormatInt(l.postsT2, 10) +
		";l3:" + strconv.FormatInt(l.postsT3(), 10) +
		";inherited:" + inherited
}
func postLevel(c *Court, who address) int64 {
	l := ladderFor(c)
	sup, sealed := boardSupply(c)
	if !sealed {
		return 0
	}
	var s int64
	if r := lookupStanding(c, who); r != nil {
		s = r.score
	}
	switch {
	case s >= sup*l.t3Bps/10_000:
		return 3
	case s >= sup*l.t2Bps/10_000:
		return 2
	case s >= sup*l.t1Bps/10_000:
		return 1
	}
	if r := lookupStanding(c, who); r != nil && r.passHeld {
		return 1
	}
	return 0
}
func postsPerDayAt(l ladder, level int64) int64 {
	switch level {
	case 3:
		return l.postsT3()
	case 2:
		return l.postsT2
	case 1:
		return l.postsEntry
	}
	return 0
}
func PostLevel(courtSlug string, who address) int64 {
	return postLevel(mustCourt(courtSlug), who)
}
func PostsPerDay(courtSlug string, who address) int64 {
	c := mustCourt(courtSlug)
	return postsPerDayAt(ladderFor(c), postLevel(c, who))
}
func BuyCommentPass(cur realm, courtSlug string) int64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	touch(c)
	if r := lookupStanding(c, who); r != nil && r.passHeld {
		panic("kourtv2: this address already holds a pass in this court")
	}
	price := passPriceFor(c)
	if price <= 0 {
		if _, sealed := boardSupply(c); !sealed {
			panic("kourtv2: this court has not completed a sealed epoch yet; its board is not open")
		}
		panic("kourtv2: this court cannot price a pass yet — it has no supply")
	}
	mustSpendable(c, who, price)
	c.coin.Burn(who, price)
	getStanding(c, who).passHeld = true
	return price
}
func HoldsPass(courtSlug string, who address) bool {
	r := lookupStanding(mustCourt(courtSlug), who)
	return r != nil && r.passHeld
}
const secsPerDay = int64(86_400)
func bucketAt(tokens, lastRefill, rate, now int64) (avail, stamp int64) {
	if rate <= 0 {
		return 0, lastRefill
	}
	if lastRefill == 0 {
		return rate, now
	}
	stamp = lastRefill
	if gain := (now - lastRefill) * rate / secsPerDay; gain > 0 {
		tokens = satAdd(tokens, gain)
		stamp += gain * secsPerDay / rate
	}
	if tokens > rate {
		tokens = rate
	}
	if tokens < 0 {
		tokens = 0
	}
	return tokens, stamp
}
func refill(c *Court, who address, r *standingRow) int64 {
	rate := postsPerDayAt(ladderFor(c), postLevel(c, who))
	r.tokens, r.lastRefill = bucketAt(r.tokens, r.lastRefill, rate, nowTime())
	return r.tokens
}
func mustSpendPost(c *Court, who address) {
	lvl := postLevel(c, who)
	if lvl == 0 {
		if _, sealed := boardSupply(c); !sealed {
			panic("kourtv2: this court has not completed a sealed epoch yet; its board is not open")
		}
		panic("kourtv2: you cannot post in this court yet — earn standing, or buy an entry pass")
	}
	r := getStanding(c, who)
	if refill(c, who, r) < 1 {
		panic("kourtv2: your posting allowance for now is spent — level " +
			strconv.FormatInt(lvl, 10) + " allows " +
			strconv.FormatInt(postsPerDayAt(ladderFor(c), lvl), 10) + " a day")
	}
	r.tokens--
}
func PostsAvailable(courtSlug string, who address) int64 {
	c := mustCourt(courtSlug)
	r := lookupStanding(c, who)
	if r == nil {
		return 0
	}
	avail, _ := bucketAt(r.tokens, r.lastRefill, postsPerDayAt(ladderFor(c), postLevel(c, who)), nowTime())
	return avail
}
func renderStanding(slug, addrArg string) string {
	c := mustCourt(slug)
	who := address(addrArg)
	if !who.IsValid() {
		return "## Not found\nThat is not a valid address."
	}
	l := ladderFor(c)
	sup, sealed := boardSupply(c)
	lvl := postLevel(c, who)
	var b strings.Builder
	b.WriteString("# Standing in " + courtNameFor(c) + "\n\n")
	b.WriteString("`" + sanitize.InlineText(who.String()) + "`\n\n")
	if !sealed {
		b.WriteString("This court is too new to have a board. Its thresholds are quoted\n" +
			"against a sealed epoch and it has not completed one yet; comments open\n" +
			"as soon as it has.\n\n")
		b.WriteString(helpLink + "\n")
		return b.String()
	}
	var score, hw int64
	if r := lookupStanding(c, who); r != nil {
		score, hw = r.score, r.highWater
	}
	frozenAt, frozenUntil := boardFrozenAt(c, who)
	if frozenUntil != 0 {
		when := "block " + strconv.FormatInt(frozenUntil, 10)
		if frozenAt != 0 {
			when = strconv.FormatInt(frozenAt, 10) + " (" + when + ")"
		}
		b.WriteString("> **This court's moderators have frozen you out of its boards**\n" +
			"> until " + when + ".\n>\n" +
			"> It reaches comments and upvotes and nothing else: you may still stake,\n" +
			"> vote, answer, dispute, flag, open claims, withdraw, draw emission, and\n" +
			"> take every election action. An entry pass will not lift it, and buying\n" +
			"> one now would burn coin for nothing.\n>\n" +
			"> The court's [moderation log](/r/g13khfsjnnq6g3lz2e997jejc9kvlz2x5yx08dr0/kourt:" + slug +
			"/mod) records who acted and why.\n\n")
	}
	b.WriteString("## What you may do\n\n")
	b.WriteString("- level: **" + strconv.FormatInt(lvl, 10) + "** of 3\n")
	b.WriteString("- comments: **" + strconv.FormatInt(postsPerDayAt(l, lvl), 10) +
		" a day**, " + strconv.FormatInt(PostsAvailable(slug, who), 10) + " available now\n")
	b.WriteString("- per claim: at most " + strconv.Itoa(maxBoardRowsPerAuthor) + " comments\n")
	if lvl == 0 {
		if hw > score {
			b.WriteString("\nA moderator slash took your standing to zero, and with it the\n" +
				"entry pass if you held one — the burn is not refunded. A successor\n" +
				"set, or the platform, can restore up to the high-water mark below.\n")
		}
		if frozenUntil == 0 {
			if hw > score {
				b.WriteString("You can also earn back from zero, or buy a new pass for " +
					strconv.FormatInt(passPriceFor(c), 10) + " " + qualifiedSymbol(c) + ".\n")
			} else {
				b.WriteString("\nYou cannot comment here yet. Earn standing below, or buy an entry\n" +
					"pass for " + strconv.FormatInt(passPriceFor(c), 10) + " " +
					qualifiedSymbol(c) + " (burned, one-off).\n")
			}
		}
	}
	b.WriteString("\n## Standing\n\n")
	b.WriteString("- earned: **" + strconv.FormatInt(score, 10) + "**\n")
	b.WriteString("- high-water mark: " + strconv.FormatInt(hw, 10) +
		" — what a moderator slash can be restored toward\n")
	b.WriteString("- entry pass: " + yesNo(HoldsPass(slug, who)) + "\n")
	writeStandingFrom(&b, c, who)
	b.WriteString("\n## The rungs, in this court\n\n")
	for _, k := range []struct {
		name string
		bps  int64
		rate int64
	}{{"1", l.t1Bps, l.postsEntry}, {"2", l.t2Bps, l.postsT2}, {"3", l.t3Bps, l.postsT3()}} {
		b.WriteString("- level " + k.name + ": " + strconv.FormatInt(sup*k.bps/10_000, 10) +
			" standing (" + strconv.FormatInt(k.bps, 10) + " bps of supply) → " +
			strconv.FormatInt(k.rate, 10) + " a day\n")
	}
	b.WriteString("\nEach rung is a **share of this court's supply**, not a fixed " +
		"number, so the bar rises as the court grows. Standing itself is never " +
		"taken except by a logged moderator slash — but a score that does not " +
		"move can still fall below a rung it used to clear.\n")
	b.WriteString("\n## How standing is earned\n\n")
	b.WriteString("Only where the court adjudicated something, and always in proportion\n" +
		"to your own capital that the act committed or destroyed:\n\n")
	b.WriteString("- a quality flag whose slash **settled** — the full bar, two thirds low\n")
	b.WriteString("- **prevailing in a dispute** — an uphold against real opposition, or an overturn\n")
	b.WriteString("- authoring a claim the court rated **HIGH** — seeded claims earn nothing\n")
	b.WriteString("- **winning conviction** on a resolved claim; half where nobody disputed it\n\n")
	b.WriteString("Never earned: commenting, being upvoted, buying " +
		qualifiedSymbol(c) + ", or buying the pass.\n")
	b.WriteString("Standing does not decay. A moderator may slash it for abuse; the\n")
	b.WriteString("high-water mark above is what a successor set can restore.\n")
	b.WriteString("\n## The answer record\n\n")
	b.WriteString("- contested-and-upheld answers: **" +
		strconv.FormatInt(int64(AnswerRecord(slug, who)), 10) + "**\n")
	b.WriteString("\n_Adjudicated — moderators cannot change this._\n")
	return b.String()
}
func renderStandingIndex(slug string) string {
	c := mustCourt(slug)
	l := ladderFor(c)
	var b strings.Builder
	b.WriteString("# Standing in " + courtNameFor(c) + "\n\n")
