func DocketSeries(courtSlug string, ids string, window int64) string {
	c := mustCourt(courtSlug)
	now := heightNow()
	out := strings.Builder{}
	sent := 0
	for _, part := range strings.Split(ids, ",") {
		if sent >= seriesPageMax {
			break
		}
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		id, err := strconv.ParseUint(part, 10, 64)
		if err != nil {
			continue
		}
		v := c.claims.Get(beClaimKey(id))
		if v == nil {
			continue
		}
		cs := v.(*claimState)
		oi, oiMature := cs.oi.Average(now, window)
		yes, yesMature := cs.yes.Average(now, window)
		if sent > 0 {
			out.WriteString(";")
		}
		out.WriteString(strconv.FormatUint(id, 10))
		out.WriteString(":" + strconv.FormatInt(cs.yesStake, 10))
		out.WriteString(":" + strconv.FormatInt(cs.noStake, 10))
		out.WriteString(":" + strconv.FormatInt(convToCC(cs.yesConvHi, cs.yesConvLo), 10))
		out.WriteString(":" + strconv.FormatInt(convToCC(cs.noConvHi, cs.noConvLo), 10))
		out.WriteString(":" + strconv.FormatInt(oi, 10))
		out.WriteString(":" + boolDigit(oiMature))
		out.WriteString(":" + strconv.FormatInt(yes, 10))
		out.WriteString(":" + boolDigit(yesMature))
		sent++
	}
	return out.String()
}
const seriesPageMax = 60
func boolDigit(b bool) string {
	if b {
		return "1"
	}
	return "0"
}
func mustClaim(c *Court, id uint64) *claimState {
	v := c.claims.Get(beClaimKey(id))
	if v == nil {
		panic("kourtv2: no such claim")
	}
	return v.(*claimState)
}
func beClaimKey(id uint64) string {
	b := [8]byte{
		byte(id >> 56), byte(id >> 48), byte(id >> 40), byte(id >> 32),
		byte(id >> 24), byte(id >> 16), byte(id >> 8), byte(id),
	}
	return string(b[:])
}

package kourt2
import (
	"strconv"
	"strings"
)
func ClaimHead(courtSlug string, claimID uint64, window int64) string {
	c := mustCourt(courtSlug)
	mustClaim(c, claimID)
	b := strings.Builder{}
	n := func(v int64) { b.WriteString(strconv.FormatInt(v, 10) + "\t") }
	i := func(v int) { b.WriteString(strconv.Itoa(v) + "\t") }
	f := func(v bool) { b.WriteString(boolDigit(v) + "\t") }
	t := func(v string) { b.WriteString(v + "\t") }
	yes, no := StakePools(courtSlug, claimID)
	cy, cn := PoolConviction(courtSlug, claimID)
	oi, oiM := TrailingOI(courtSlug, claimID, window)
	ty, tyM := TrailingYes(courtSlug, claimID, window)
	n(yes)
	n(no)
	n(cy)
	n(cn)
	n(oi)
	f(oiM)
	n(ty)
	f(tyM)
	answered := HasAnswer(courtSlug, claimID)
	settled := Settled(courtSlug, claimID)
	disputeOpen := DisputeOpen(courtSlug, claimID)
	provClose := ProvClose(courtSlug, claimID)
	f(answered)
	f(disputeOpen)
	f(settled)
	f(provClose)
	i(Provisional(courtSlug, claimID))
	f(ClaimClosed(courtSlug, claimID))
	if answered {
		who := Answerer(courtSlug, claimID)
		i(AnswerVerdict(courtSlug, claimID))
		n(AnswerBond(courtSlug, claimID))
		n(SettleDeadline(courtSlug, claimID))
