	sent := unsafe.OriginSend().AmountOf(gnotDenom)
	if sent < price {
		panic("kourtv2: starting a court burns at least " + ugnotAmt(price) +
			" GNOT, you sent " + ugnotAmt(sent))
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), chain.PackageAddress(burnSinkPath),
		chain.Coins{chain.NewCoin(gnotDenom, sent)})
}

package kourt2
import "strconv"
const (
	tierHidden   uint8 = 0
	tierListed   uint8 = 1
	tierFeatured uint8 = 2
)
var directoryAdmin address
func SetTier(cur realm, courtSlug string, tier int) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	if !isGlobalMod(who) {
		panic("kourtv2: only a global DAO member may set a court's tier")
	}
	if tier < int(tierHidden) || tier > int(tierFeatured) {
		panic("kourtv2: tier is 0 (hidden), 1 (listed), or 2 (featured)")
	}
	c := mustCourt(courtSlug)
	if c.tier == uint8(tier) {
		return
	}
	c.tier = uint8(tier)
	emitGlobalAct(c.id, 0, "tier:"+strconv.Itoa(tier), who)
}
