	})
	return out
}

package kourt2
import (
	"strconv"
	governor "gno.land/p/g13khfsjnnq6g3lz2e997jejc9kvlz2x5yx08dr0/governor/v0"
	grc20votes "gno.land/p/g13khfsjnnq6g3lz2e997jejc9kvlz2x5yx08dr0/grc20votes/v0"
	bptree "gno.land/p/nt/bptree/v0"
)
const disputeKindName = "dispute"
const quorumSupplyBps = int64(500)
const finalizeGraceBlocks = int64(120_960)
type disputeKind struct{}
func (disputeKind) Name() string { return disputeKindName }
func (disputeKind) Describe(payload string) string {
	return "resolve a disputed claim by a token vote (see the court page for the claim)"
}
func (disputeKind) Check(payload string) error { return nil }
func (disputeKind) Do(_ int, rlm realm, payload string) error { return nil }
func disputeRules(p Params) governor.Rules {
	return governor.NewRules(5000, p.disputeThresholdBps, p.votingBlocks, 1, p.graceBlocks, 0)
}
func OpenDispute(cur realm, courtSlug string, claimID uint64) int64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if cs.frozenAt == 0 {
		panic("kourtv2: there is no answer to dispute")
	}
	if who == cs.answerer {
		panic("kourtv2: the answerer cannot dispute their own answer")
	}
	if cs.disputeOpen {
		panic("kourtv2: a dispute is already open on this claim")
	}
	if cs.verdictAt != 0 {
		panic("kourtv2: the verdict is final")
	}
	now := heightNow()
	if cs.provisional < 0 {
		if passed, known := pastDeadline(cs.answeredAtTime, settleSecs); (known && passed) ||
			(!known && now >= cs.answerHeight+settleDelay) {
			panic("kourtv2: the dispute window has passed; the answer settles undisputed")
		}
	} else if escrowPassed(cs) {
		panic("kourtv2: the escrow window has passed; Finalize the verdict")
	}
	touch(c)
	bond := cs.disputeBond0()
	mustSpendable(c, who, bond)
	c.coin.Transfer(who, c.escrow, bond)
	floor := quorumFloor(c, cs.xBarFrozen)
	cs.round++
	payload := strconv.FormatUint(claimID, 10) + "|" + strconv.FormatInt(cs.round, 10)
	pid := c.gov.ProposeWithQuorum(c.escrow, disputeKindName, payload, "dispute", floor)
	cs.proposalID = pid
	cs.disputeOpen = true
	cs.disputeOpenedTime = nowTime()
	cs.disputeBond = bond
	cs.disputer = who
	return pid
}
func VoteDispute(cur realm, courtSlug string, claimID uint64, choice string) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if !cs.disputeOpen {
		panic("kourtv2: no open dispute on this claim")
	}
	if isParticipant(cs, who) {
		panic("kourtv2: a participant may not vote on their own claim's verdict")
	}
	held := voteCap(c, who)
	if held <= 0 {
		panic("kourtv2: you hold none of this court's coin, and voting weight is " +
			"the lesser of what you held when the round opened and what you hold now")
	}
	govChoice := choice
	switch choice {
	case voteYes, voteNo:
	case voteSpam:
		govChoice = govAbstain
	default:
		panic("kourtv2: a dispute vote is \"yes\" to overturn, \"no\" to uphold, " +
			"or \"spam\" to say the claim was not worth judging")
	}
	c.gov.VoteWithCap(who, cs.proposalID, govChoice, held)
	if cs.voted == nil {
		cs.voted = bptree.NewBPTree32()
	}
	cs.voted.Set("d"+beClaimKey(uint64(cs.proposalID))+string(who), choice)
	_, dw, ok := c.gov.VoteOf(cs.proposalID, who)
	if !ok {
		panic("kourtv2: the governor did not record the vote it just accepted")
	}
	cs.voted.Set("dw"+beClaimKey(uint64(cs.proposalID))+string(who), dw)
	lockVote(c, who, voteLockDispute, int64(claimID), cs.proposalID, dw)
}
func ResolveDispute(cur realm, courtSlug string, claimID uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if !cs.disputeOpen {
		panic("kourtv2: no dispute to resolve")
	}
	if c.gov.State(cs.proposalID) == "active" {
		panic("kourtv2: the dispute vote is still open")
	}
	touch(c)
	yes, no, spamW, _ := c.gov.Tally(cs.proposalID)
	cast := yes + no + spamW
	floor := c.gov.QuorumFloor(cs.proposalID)
	firstResolution := cs.provisional < 0
	switch {
	case cast < floor:
		half := cs.disputeBond / 2
		if half > 0 {
			c.coin.Transfer(c.escrow, cs.disputer, half)
		}
		if rest := cs.disputeBond - half; rest > 0 {
			c.coin.Burn(c.escrow, rest)
		}
		cs.disputeBond = 0
		if firstResolution {
			cs.provisional = cs.answer
		}
		cs.failedRounds++
		if cs.failedRounds >= maxFailedRounds {
			provCloseClaim(c, cs)
		}
	case spamDiscards(spamW, cast):
		spamDiscardClaim(c, cs, spamW, cast)
	case yes > 0 && yes*grc20votes.Bps >= (yes+no)*c.params.disputeThresholdBps:
		posted := cs.disputeBond
		burned := cs.answerBond
		if burned > 0 {
			c.coin.Burn(c.escrow, burned)
			cs.answerBond = 0
			cs.overturnBy = cs.disputer
			cs.overturnBond = posted
		}
		if posted > 0 {
			c.coin.Transfer(c.escrow, cs.disputer, posted)
			cs.disputeBond = 0
		}
		if comp := compAmount(posted, burned); comp > 0 {
			enqueueSenior(c, cs.disputer, comp, "comp")
		}
		cs.provisional = int8(oppositeSide(int(cs.answer)))
		cs.failedRounds = 0
		cs.decidedRounds++
		cs.decidedPID, cs.carrotChoice, cs.carrotDenom = cs.proposalID, "yes", yes
		cs.spamW, cs.spamTotalW = spamW, cast
	default:
		burned := cs.disputeBond
		if burned > 0 {
			c.coin.Burn(c.escrow, burned)
			cs.disputeBond = 0
		}
		if comp := compAmount(cs.answerBond0, burned); comp > 0 {
			enqueueSenior(c, cs.answerer, comp, "comp")
		}
		if yes >= credWeightFloor(c, cs.proposalID)/4 {
			cs.credEligible = true
		}
		cs.provisional = cs.answer
		cs.failedRounds = 0
		cs.decidedRounds++
		cs.decidedPID, cs.carrotChoice, cs.carrotDenom = cs.proposalID, "no", no
		cs.spamW, cs.spamTotalW = spamW, cast
	}
	if firstResolution && !cs.provClose {
		w := escrowWindow(c, cs)
		if cs.failedRounds > 0 {
			if lw := ladderWindow(c.params); lw > w {
				w = lw
			}
		}
		cs.escrowUntil = heightNow() + w
		cs.escrowUntilAt = nowTime() + blocksToSecs(w)
	}
	cs.disputeOpen = false
}
func (cs *claimState) disputeBond0() int64 {
	base := cs.xBarFrozen * disputeBondXBps / 10000
	if arm := cs.answerBond0 * disputeBondOfAnswerBps / 10000; arm < base {
		base = arm
	}
	if base < 1 {
		base = 1
	}
	shift := cs.failedRounds
	if shift > maxFailedRounds-1 {
		shift = maxFailedRounds - 1
	}
	return mustMul(base, int64(1)<<uint(shift))
}
func compAmount(ownBond, burned int64) int64 {
	comp := mustMul(compOwnX, ownBond)
	if arm := burned * compOfBurnBps / 10000; arm < comp {
		comp = arm
	}
	if comp < 0 {
		comp = 0
	}
	return comp
}
func spamDiscards(spamW, cast int64) bool { return spamW*2 > cast }
func spamBurnsDeposit(spamW, cast int64) bool { return spamW*3 >= cast*2 }
func spamDiscardClaim(c *Court, cs *claimState, spamW, cast int64) {
	cs.spamClosed = true
	cs.provClose = true
	cs.verdictAt = heightNow()
	cs.verdictAtTime = nowTime()
	cs.route = "spam"
	cs.spamW, cs.spamTotalW = spamW, cast
	cs.decidedPID, cs.carrotChoice, cs.carrotDenom = cs.proposalID, voteSpam, spamW
	if cs.answerBond > 0 {
		settleAnswerBond(c, cs)
	}
	if cs.disputeBond > 0 {
		c.coin.Transfer(c.escrow, cs.disputer, cs.disputeBond)
		cs.disputeBond = 0
	}
	burnDeposit := spamBurnsDeposit(spamW, cast)
	if cs.deposit > 0 {
		if burnDeposit {
			c.coin.Burn(c.escrow, cs.deposit)
		} else {
			c.coin.Transfer(c.escrow, cs.author, cs.deposit)
		}
		c.deposit -= cs.deposit
		cs.deposit = 0
	}
	if cs.fee > 0 {
		c.coin.Burn(c.escrow, cs.fee)
		c.deposit -= cs.fee
		cs.fee = 0
	}
	releasePriority(c, cs.answerer, cs.id)
	stripExit(c, cs)
	releaseMetaLatchIfMeta(c, cs)
}
func provCloseClaim(c *Court, cs *claimState) {
	cs.provClose = true
	cs.verdictAt = heightNow()
	cs.verdictAtTime = nowTime()
	cs.route = "closed"
	if cs.answerBond > 0 {
		settleAnswerBond(c, cs)
	}
	if cs.deposit > 0 {
		c.coin.Transfer(c.escrow, cs.author, cs.deposit)
		c.deposit -= cs.deposit
		cs.deposit = 0
	}
	if cs.fee > 0 {
		c.coin.Transfer(c.escrow, cs.author, cs.fee)
		c.deposit -= cs.fee
		cs.fee = 0
	}
	releasePriority(c, cs.answerer, cs.id)
	stripExit(c, cs)
	releaseMetaLatchIfMeta(c, cs)
}
func Finalize(cur realm, courtSlug string, claimID uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if cs.verdictAt != 0 {
		panic("kourtv2: already final")
	}
	if cs.disputeOpen {
		panic("kourtv2: a dispute is active; cannot finalize")
	}
	if cs.provisional < 0 {
		panic("kourtv2: no provisional verdict to finalize")
	}
	now := heightNow()
	if !escrowPassed(cs) {
		panic("kourtv2: the escrow window has not passed")
	}
	if passed, known := pastDeadline(cs.escrowUntilAt, finalizeGraceSecs); ((known && !passed) ||
		(!known && now < cs.escrowUntil+finalizeGraceBlocks)) && !isParticipant(cs, who) {
		panic("kourtv2: Finalize is participant-only for its first week")
	}
	touch(c)
	cs.verdictAt = now
	cs.verdictAtTime = nowTime()
	cs.route = "vote"
	trimClaimHistory(c, cs, uint32(cs.frozenAt/epochBlocks)+1)
	if cs.answerBond > 0 {
		settleAnswerBond(c, cs)
	}
	if cs.provisional != cs.answer {
		resetOverturned(c, cs.answerer)
	} else if cs.decidedRounds > 0 && cs.credEligible {
		creditUpheld(c, cs.answerer)
	}
	creditDisputeResolved(c, cs)
	releasePriority(c, cs.answerer, claimID)
}
func VotableSupply(courtSlug string) (raw, escrowed, votable int64) {
	c := mustCourt(courtSlug)
	at := c.coin.Epoch()
	if at <= 1 {
		return 0, 0, 0
	}
	at--
	raw = c.coin.PastTotal(at)
	escrowed = c.coin.PastVotes(c.escrow, at)
	votable = raw - escrowed
	if votable < 0 {
		votable = 0
	}
	return raw, escrowed, votable
}
func QuorumFloorOf(courtSlug string, claimID uint64) int64 {
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if cs.disputeOpen {
		return c.gov.QuorumFloor(cs.proposalID)
	}
	return quorumFloor(c, cs.xBarFrozen)
}
func isParticipant(cs *claimState, who address) bool {
	if who == cs.author || who == cs.answerer {
		return true
	}
	return cs.stakers.Get(posKey(who, sideYES)) != nil ||
		cs.stakers.Get(posKey(who, sideNO)) != nil
}
func quorumFloor(c *Court, xbar int64) int64 {
	at := c.coin.Epoch() - 1
	supply := c.coin.PastTotal(at)
	votable := supply - c.coin.PastVotes(c.escrow, at)
	if votable < 0 {
		votable = 0
	}
	floor := xbar
	if third := votable / 3; third < floor {
		floor = third
	}
	if floor < 1 {
		floor = 1
	}
	return floor
}
func oppositeSide(side int) int {
	if side == sideYES {
		return sideNO
	}
	return sideYES
}
func escrowWindow(c *Court, cs *claimState) int64 {
	extraDays := mulDiv128(cs.xBarFrozen, c.crv.Price(c.minted), 500_000_000)
	room := (c.params.escrowMaxBlocks - c.params.escrowMinBlocks) / oneDayBlocks
	if extraDays >= room {
		return c.params.escrowMaxBlocks
	}
	return c.params.escrowMinBlocks + extraDays*oneDayBlocks
}
const (
	voteYes  = "yes"
	voteNo   = "no"
	voteSpam = "spam"
	govAbstain = "abstain"
)
const oneDayBlocks = int64(24) * epochBlocks
func DisputeOpen(courtSlug string, claimID uint64) bool {
	return mustClaim(mustCourt(courtSlug), claimID).disputeOpen
}
func DisputeProposal(courtSlug string, claimID uint64) int64 {
	return mustClaim(mustCourt(courtSlug), claimID).proposalID
}
func Provisional(courtSlug string, claimID uint64) int {
	return int(mustClaim(mustCourt(courtSlug), claimID).provisional)
}
func FailedRounds(courtSlug string, claimID uint64) int64 {
	return mustClaim(mustCourt(courtSlug), claimID).failedRounds
}
func ProvClose(courtSlug string, claimID uint64) bool {
	return mustClaim(mustCourt(courtSlug), claimID).provClose
}
func EscrowUntil(courtSlug string, claimID uint64) int64 {
	return mustClaim(mustCourt(courtSlug), claimID).escrowUntil
}
func DisputeVoteCloses(courtSlug string, claimID uint64) int64 {
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if !cs.disputeOpen || cs.proposalID == 0 {
		return 0
	}
	_, closes, _, _ := c.gov.Timings(cs.proposalID)
	return closes
}
func DisputeBondNext(courtSlug string, claimID uint64) int64 {
	cs := mustClaim(mustCourt(courtSlug), claimID)
	if cs.frozenAt == 0 {
		return 0
	}
	return cs.disputeBond0()
}
func escrowPassed(cs *claimState) bool {
	passed, known := pastDeadline(cs.escrowUntilAt, 0)
	return (known && passed) || (!known && heightNow() >= cs.escrowUntil)
}
func Reopenable(courtSlug string, claimID uint64) bool {
	cs := mustClaim(mustCourt(courtSlug), claimID)
	return cs.provisional >= 0 && cs.verdictAt == 0 && !cs.disputeOpen &&
		!escrowPassed(cs)
}
func ladderWindow(p Params) int64 {
	return (maxFailedRounds-2)*p.votingBlocks + (maxFailedRounds-1)*p.graceBlocks + 1
}
func credWeightFloor(c *Court, pid int64) int64 {
	engaged, _ := c.gov.Snapshot(pid)
	return mulDiv128(engaged, quorumSupplyBps, grc20votes.Bps)
}
func credWeightFloorAt(c *Court, at uint32) int64 {
	return mulDiv128(c.coin.EngagedTotal(at), quorumSupplyBps, grc20votes.Bps)
}

package kourt2
import (
	"strconv"
	"strings"
	sanitize "gno.land/p/nt/markdown/sanitize/v0"
)
const electionPath = "election"
func renderElection(slug string) string {
	if !Exists(slug) {
		return "## Not found\nNo court by that slug."
	}
	c := mustCourt(slug)
	base := "/r/g13khfsjnnq6g3lz2e997jejc9kvlz2x5yx08dr0/kourt2:" + slug
	var b strings.Builder
	b.WriteString("# Electing the moderators of " + courtNameFor(c) + "\n\n")
	b.WriteString("[← " + courtNameFor(c) + "](" + base + ") · [moderation log](" +
		base + "/mod)\n\n")
	b.WriteString("A court's moderators answer claims, curate its folders, and can " +
		"hide a claim, hide a comment, slash somebody's standing, or freeze an " +
		"address out of the boards. **This ballot is the only way the court's " +
		"holders replace them.**\n\n")
	cm := c.mod
	if cm == nil || cm.election == nil || cm.election.resolved {
		writeNoElection(&b, c, cm)
		b.WriteString("\n" + helpLink + "\n")
		return b.String()
	}
	writeOpenElection(&b, c, cm, base)
	b.WriteString("\n" + helpLink + "\n")
	return b.String()
}
func writeNoElection(b *strings.Builder, c *Court, cm *courtMod) {
	b.WriteString("## No election is open\n\n")
	if cm == nil || cm.n == 0 {
		b.WriteString("This court has no moderator set yet — its creator holds the " +
			"seat until an election or an appointment changes that.\n")
	} else {
		b.WriteString("- seats held now: **" + strconv.Itoa(cm.n) + "**, " +
			strconv.Itoa(cm.m) + " of whom must agree for a moderation act\n")
	}
	now := heightNow()
	if cm != nil && electionCooldownOpen(cm) {
		b.WriteString("- this court is in its post-election cooldown until block **" +
			strconv.FormatInt(cm.electionCooldownUntil, 10) + "** (now " +
			strconv.FormatInt(now, 10) + "); no ballot can open before then\n\n")
		return
	}
	b.WriteString("- a ballot **can be opened now**\n\n")
	b.WriteString("Opening one takes two calls: `RegisterModCandidate` records a " +
		"proposed set of moderators and returns its id, and `OpenElection` puts " +
		"that id on a ballot. Any holder may do both.\n\n")
}
func writeOpenElection(b *strings.Builder, c *Court, cm *courtMod, base string) {
	e := cm.election
	now := heightNow()
	b.WriteString("## A ballot is open\n\n")
	switch {
	case !nominationClosed(e):
		b.WriteString("**Nominating.** Candidate sets may be added until block **" +
			strconv.FormatInt(e.nominateEnd, 10) + "**; voting runs from then " +
			"until block **" + strconv.FormatInt(e.voteEnd, 10) + "**.\n\n")
	case !votingClosed(e):
		b.WriteString("**Voting.** Nominations closed at block " +
			strconv.FormatInt(e.nominateEnd, 10) + "; the ballot closes at block **" +
			strconv.FormatInt(e.voteEnd, 10) + "**.\n\n")
	default:
		b.WriteString("**Closed and awaiting resolution.** The ballot shut at block " +
			strconv.FormatInt(e.voteEnd, 10) + ". Anyone may call `ResolveElection` " +
			"to apply the result below.\n\n")
	}
	b.WriteString("- now: block " + strconv.FormatInt(now, 10) + "\n")
	b.WriteString("- a candidate set costs a bond of **" +
		strconv.FormatInt(e.bond, 10) + " " + qualifiedSymbol(c) + "**\n")
	b.WriteString("- weights are pinned at the epoch the ballot opened, so buying " +
		"coin now does not add voting weight to it\n\n")
	writeBallotLines(b, c, e)
	writeTurnoutBar(b, c, e)
}
func writeBallotLines(b *strings.Builder, c *Court, e *election) {
	b.WriteString("## On the ballot\n\n")
	rows := 0
	e.lines.Iterate("", "", func(_ string, v any) bool {
		l, ok := v.(*ballotLine)
		if !ok {
			return false
		}
		rows++
		b.WriteString("- **set #" + strconv.FormatUint(l.candID, 10) + "** — " +
			strconv.FormatInt(l.weight, 10) + " " + qualifiedSymbol(c) + " approving\n")
		if cv := c.mod.candidates.Get(beClaimKey(l.candID)); cv != nil {
			cand := cv.(*modCandidate)
			b.WriteString("  - would seat " + strconv.Itoa(len(cand.members)) +
				", " + strconv.Itoa(cand.m) + " of whom must agree\n")
			for _, m := range cand.members {
				b.WriteString("  - `" + sanitize.InlineText(m.String()) + "`\n")
			}
		}
		return rows >= renderPageSize
	})
	if rows == 0 {
		b.WriteString("_No candidate sets yet._ Until one is nominated there is " +
			"nothing to elect, and the current moderators stay.\n\n")
	} else {
		b.WriteString("\n")
	}
	b.WriteString("- **keep the current moderators** — " +
		strconv.FormatInt(e.retainW, 10) + " " + qualifiedSymbol(c) + " approving\n\n")
}
func writeTurnoutBar(b *strings.Builder, c *Court, e *election) {
	b.WriteString("## Turnout\n\n")
	b.WriteString("- cast so far: **" + strconv.FormatInt(e.turnout, 10) + " " +
		qualifiedSymbol(c) + "**\n")
	b.WriteString("- the bar: **" + strconv.FormatInt(e.floor, 10) + " " +
		qualifiedSymbol(c) + "**, fixed when the ballot opened\n")
	if e.turnout < e.floor {
		b.WriteString("- still needed: **" + strconv.FormatInt(e.floor-e.turnout, 10) +
			" " + qualifiedSymbol(c) + "**\n\n")
	} else {
		b.WriteString("- the bar is cleared\n\n")
	}
	b.WriteString("> **Falling short is not a draw.** If the ballot closes with less " +
		"than the bar cast, nothing is installed and the current moderators keep " +
		"their seats — the same outcome as a vote to retain them.\n>\n" +
		"> And the bar is a share of this court's coin **including coin that " +
		"cannot vote**: it nets out only the court's own escrow, so coin held at " +
		"a wrapper's address counts toward the pool the bar was measured against " +
		"while no key can cast it. The share of actually-castable weight you need " +
		"is therefore larger than the bar looks.\n\n")
}

package kourt2
import (
	"chain"
	"strconv"
)
const (
	seniorEnqueuedEvent = "SeniorEnqueued"
	seniorPaidEvent     = "SeniorPaid"
)
type entitlement struct {
	to      address
	amount  int64
	start   int64
	paid    int64
	purpose string
}
func touch(c *Court) {
	now := heightNow()
	for c.lastAccrual < now {
		boundary := c.createdAt + (c.periodIndex+1)*periodBlocks
		segEnd := now
		if boundary < segEnd {
			segEnd = boundary
		}
		accrueSegment(c, segEnd-c.lastAccrual)
		advanceRateAcc(c, segEnd-c.lastAccrual)
		c.lastAccrual = segEnd
		if segEnd == boundary {
			rollPeriod(c)
		}
	}
}
func accrueSegment(c *Court, blocks int64) {
	if blocks <= 0 || c.curPeriodBudget <= 0 {
		return
	}
	if c.reservoirR() >= c.rMax() && c.cumAccrual >= c.reservedTail {
		return
	}
	num := mustAdd(mustMul(c.curPeriodBudget, blocks), c.accrualRem)
	c.cumAccrual = mustAdd(c.cumAccrual, num/periodBlocks)
	c.accrualRem = num % periodBlocks
}
func advanceRateAcc(c *Court, blocks int64) {
	if blocks <= 0 {
		return
	}
	c.rateAccFP = mustAdd(c.rateAccFP, mustMul(rateBpsFP(c), blocks))
}
func rollPeriod(c *Court) {
	c.periodIndex++
	c.curBudgetBpsFP = c.curBudgetBpsFP * stepDownNum / stepDownDen
	minted := c.emittedTotal - c.emittedAtRoll
	c.emittedAtRoll = c.emittedTotal
	c.emaMinted = (3*c.emaMinted + minted) / 4
	s := c.coin.TotalSupply()
	if s > 0 {
		if c.emaMinted < 0 {
			panic("kourtv2: negative realized mint")
		}
		dReal := mulDiv128(c.emaMinted, 10_000*1_000_000, s)
		if dReal < c.curBudgetBpsFP {
			c.dEffBpsFP = dReal
		} else {
			c.dEffBpsFP = c.curBudgetBpsFP
		}
		if c.absBudget > 0 {
			c.absBudget = c.absBudget * stepDownNum / stepDownDen
			c.curPeriodBudget = c.absBudget
		} else {
			c.curPeriodBudget = mulDiv128(s, c.curBudgetBpsFP, 10_000*1_000_000)
		}
	} else {
		c.dEffBpsFP = 0
		c.curPeriodBudget = 0
	}
}
func (c *Court) reservoirR() int64 {
	past := c.cumAccrual - c.reservedTail
	if past < 0 {
		past = 0
	}
	r := past - c.juniorReserved
	if r < 0 {
		r = 0
	}
	return r
}
func (c *Court) rMax() int64 { return rMaxPeriods * c.curPeriodBudget }
func enqueueSenior(c *Court, to address, amount int64, purpose string) uint64 {
	if amount <= 0 {
		panic("kourtv2: a senior entitlement must be positive")
	}
	start := mustAdd(c.reservedTail, c.juniorReserved)
	e := &entitlement{to: to, amount: amount, start: start, purpose: purpose}
	c.reservedTail = mustAdd(c.reservedTail, amount)
	c.seniorOwed = mustAdd(c.seniorOwed, amount)
	c.queueSeq++
	c.queue.Set(beClaimKey(c.queueSeq), e)
	chain.Emit(seniorEnqueuedEvent,
		"court", c.id,
		"seq", strconv.FormatUint(c.queueSeq, 10),
		"to", to.String(),
		"amount", strconv.FormatInt(amount, 10),
		"purpose", purpose,
	)
	return c.queueSeq
}
func reserveJunior(c *Court, want int64) int64 {
	touch(c)
	r := c.reservoirR()
	if want > r {
		want = r
	}
	if want < 0 {
		want = 0
	}
	c.juniorReserved = mustAdd(c.juniorReserved, want)
	return want
}
func mintEmission(c *Court, to address, amount int64) {
	if amount <= 0 {
		return
	}
	c.coin.Mint(to, amount)
	c.emittedTotal = mustAdd(c.emittedTotal, amount)
}
func PullSenior(cur realm, courtSlug string, seq uint64) int64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	c := mustCourt(courtSlug)
	touch(c)
	v := c.queue.Get(beClaimKey(seq))
	if v == nil {
		panic("kourtv2: no such entitlement")
	}
	e := v.(*entitlement)
	covered := c.cumAccrual - e.start
	if covered > e.amount {
		covered = e.amount
	}
	pay := covered - e.paid
	if pay <= 0 {
		return 0
	}
	e.paid += pay
	c.seniorOwed -= pay
	c.seniorPaid = mustAdd(c.seniorPaid, pay)
	mintEmission(c, e.to, pay)
	chain.Emit(seniorPaidEvent,
		"court", c.id,
		"seq", strconv.FormatUint(seq, 10),
		"to", e.to.String(),
		"paid", strconv.FormatInt(pay, 10),
		"remaining", strconv.FormatInt(e.amount-e.paid, 10),
	)
	return pay
}
func Reservoir(courtSlug string) int64  { return mustCourt(courtSlug).reservoirR() }
func SeniorOwed(courtSlug string) int64 { return mustCourt(courtSlug).seniorOwed }
func SeniorEntitlement(courtSlug string, seq uint64) (to address, amount, paid, payable int64) {
	c := mustCourt(courtSlug)
	v := c.queue.Get(beClaimKey(seq))
	if v == nil {
		panic("kourtv2: no such entitlement")
	}
	e := v.(*entitlement)
	covered := c.cumAccrual - e.start
	if covered > e.amount {
		covered = e.amount
	}
	p := covered - e.paid
	if p < 0 {
		p = 0
	}
	return e.to, e.amount, e.paid, p
}
func QueueLen(courtSlug string) uint64 { return mustCourt(courtSlug).queueSeq }
func Poke(cur realm, courtSlug string) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	touch(mustCourt(courtSlug))
}

package kourt2
import (
	"strconv"
	"strings"
	bptree "gno.land/p/nt/bptree/v0"
)
const maxFolderTextLen = 200
const (
	maxFolderDepth = 4
	maxFolderItems = 200
	maxFolders = 100
)
type folder struct {
	id     uint64
	name   string
	desc   string
	items  []uint64
	purged bool
	code   string
	retired bool
	bornOf uint64
	focusByDefault bool
	parent uint64
	ord int
	image *mediaItem
}
func (cm *courtMod) folderDepth(id uint64) int {
	d := 0
	for id != 0 && d <= maxFolders {
		d++
		v := cm.folders.Get(beClaimKey(id))
		if v == nil {
			break
		}
		id = v.(*folder).parent
	}
	return d
}
func (cm *courtMod) folderHeight(id uint64) int {
	h := 1
	cm.folders.Iterate("", "", func(_ string, v any) bool {
		f, ok := v.(*folder)
		if !ok || f.parent != id {
			return false
		}
		if ch := 1 + cm.folderHeight(f.id); ch > h {
			h = ch
		}
		return false
	})
	return h
}
func (cm *courtMod) mustNestable(id, parent uint64, height int) {
	if parent == 0 {
		return
	}
	if parent == id {
		panic("kourtv2: a folder cannot contain itself")
	}
	cm.mustFolder(parent)
	for up, n := parent, 0; up != 0 && n <= maxFolders; n++ {
		if up == id {
			panic("kourtv2: that would put a folder inside itself")
		}
		v := cm.folders.Get(beClaimKey(up))
		if v == nil {
			break
		}
		up = v.(*folder).parent
	}
	if cm.folderDepth(parent)+height > maxFolderDepth {
		panic("kourtv2: folders nest at most " + strconv.Itoa(maxFolderDepth) + " deep")
	}
}
func folderAfter(a, b *folder) bool {
	ap, bp := a.ord > 0, b.ord > 0
	if ap != bp {
		return bp
	}
	if ap && a.ord != b.ord {
		return a.ord > b.ord
	}
	return a.id > b.id
}
func (cm *courtMod) folderRows() []*folder {
	out := make([]*folder, 0, maxFolders)
	cm.folders.Iterate("", "", func(_ string, v any) bool {
		if f, ok := v.(*folder); ok {
			out = append(out, f)
		}
		return false
	})
	for i := range out {
		first := true
		for j := 0; j < i; j++ {
			if out[j].parent == out[i].parent {
				first = false
				break
			}
		}
		if !first {
			continue
		}
		p := out[i].parent
		slots := make([]int, 0, len(out))
		grp := make([]*folder, 0, len(out))
		for j, g := range out {
			if g.parent == p {
				slots = append(slots, j)
				grp = append(grp, g)
			}
		}
		for a := 1; a < len(grp); a++ {
			f := grp[a]
			b := a - 1
			for b >= 0 && folderAfter(grp[b], f) {
				grp[b+1] = grp[b]
				b--
			}
			grp[b+1] = f
		}
		for k, g := range grp {
			out[slots[k]] = g
		}
	}
	return out
}
func (cm *courtMod) mustFolder(id uint64) *folder {
	v := cm.folders.Get(beClaimKey(id))
	if v == nil {
		panic("kourtv2: no such folder")
	}
	return v.(*folder)
}
func requireFolderMod(c *Court, who address) *courtMod {
	cm := ensureMod(c)
	requireActiveMod(cm, who)
	return cm
}
func folderTextOK(name, desc string) bool {
	return runeLen(name) > 0 && runeLen(name) <= maxFolderTextLen && runeLen(desc) <= maxFolderTextLen
}
func folderNameTaken(cm *courtMod, name string) bool {
	taken := false
	if cm.folders == nil {
		return false
	}
	cm.folders.Iterate("", "", func(_ string, v any) bool {
		f := v.(*folder)
		if !f.retired && f.name == name {
			taken = true
			return true
		}
		return false
	})
	return taken
}
func newFolderCore(cm *courtMod, name, desc string, parent uint64) uint64 {
	if cm.folders.Size() >= maxFolders {
		panic("kourtv2: this court already has " + strconv.Itoa(maxFolders) + " folders")
	}
	if !folderTextOK(name, desc) {
		panic("kourtv2: a folder name is 1..200 and a description at most 200 characters")
	}
	if parent != 0 {
		cm.mustNestable(0, parent, 1)
	}
	cm.folderSeq++
	id := cm.folderSeq
	cm.folders.Set(beClaimKey(id), &folder{id: id, name: name, desc: desc, parent: parent})
	return id
}
type folderProposal struct {
	id     uint64
	name   string
	desc   string
	parent uint64
	by     address
	at     int64
}
func RegisterFolderProposal(cur realm, courtSlug, name, desc string, parentID uint64) uint64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := ensureMod(c)
	if !folderTextOK(name, desc) {
		panic("kourtv2: a folder name is 1..200 and a description at most 200 characters")
	}
	if parentID != 0 {
		cm.mustNestable(0, parentID, 1)
	}
	if folderNameTaken(cm, name) {
		panic("kourtv2: this court already has a folder by that name")
	}
	if cm.folderProps == nil {
		cm.folderProps = bptree.NewBPTree32()
	}
	cm.folderPropSeq++
	id := cm.folderPropSeq
	cm.folderProps.Set(beClaimKey(id), &folderProposal{
		id: id, name: name, desc: desc, parent: parentID, by: who, at: heightNow(),
	})
	return id
}
func (cm *courtMod) mustFolderProposal(id uint64) *folderProposal {
	if cm.folderProps == nil {
		panic("kourtv2: no such folder proposal")
	}
	v := cm.folderProps.Get(beClaimKey(id))
	if v == nil {
		panic("kourtv2: no such folder proposal")
	}
	return v.(*folderProposal)
}
func CreateFolder(cur realm, courtSlug, name, desc string) uint64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := requireFolderMod(c, who)
	id := newFolderCore(cm, name, desc, 0)
	emitModAct(c.id, 0, "folder-create", who)
	return id
}
func CreateFolderIn(cur realm, courtSlug string, parentID uint64, name, desc string) uint64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := requireFolderMod(c, who)
	id := newFolderCore(cm, name, desc, parentID)
	emitModAct(c.id, 0, "folder-create", who)
	return id
}
func MoveFolder(cur realm, courtSlug string, folderID, newParent uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := requireFolderMod(c, who)
	f := cm.mustFolder(folderID)
	cm.mustNestable(folderID, newParent, cm.folderHeight(folderID))
	f.parent = newParent
	emitModAct(c.id, 0, "folder-move", who)
}
func AddToFolder(cur realm, courtSlug string, folderID, claimID uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := requireFolderMod(c, who)
	_ = mustClaim(c, claimID)
	f := cm.mustFolder(folderID)
	fileInto(f, claimID)
	emitModAct(c.id, claimID, "folder-add", who)
}
func fileInto(f *folder, claimID uint64) {
	for _, x := range f.items {
		if x == claimID {
			return
		}
	}
	if len(f.items) >= maxFolderItems {
		panic("kourtv2: a folder holds at most " + strconv.Itoa(maxFolderItems) + " claims")
	}
	f.items = append(f.items, claimID)
}
func RemoveFromFolder(cur realm, courtSlug string, folderID, claimID uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := requireFolderMod(c, who)
	f := cm.mustFolder(folderID)
	out := f.items[:0]
	found := false
	for _, x := range f.items {
		if x == claimID {
			found = true
			continue
		}
		out = append(out, x)
	}
	if !found {
		panic("kourtv2: that claim is not in the folder")
	}
	f.items = out
	emitModAct(c.id, claimID, "folder-remove", who)
}
func RenameFolder(cur realm, courtSlug string, folderID uint64, name, desc string) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := requireFolderMod(c, who)
	if runeLen(name) == 0 || runeLen(name) > maxFolderTextLen || runeLen(desc) > maxFolderTextLen {
		panic("kourtv2: a folder name is 1..200 and a description at most 200 characters")
	}
	f := cm.mustFolder(folderID)
	if f.purged {
		panic("kourtv2: this folder's text was purged and cannot be re-set")
	}
	f.name = name
	f.desc = desc
	emitModAct(c.id, 0, "folder-rename", who)
}
func SetFolderImage(cur realm, courtSlug string, folderID uint64, media string) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := requireFolderMod(c, who)
	f := cm.mustFolder(folderID)
	if f.purged {
		panic("kourtv2: this folder's text was purged and cannot be re-set")
	}
	items := parseMediaArg(media)
	if len(items) != 1 {
		panic("kourtv2: a folder carries exactly one image")
	}
	if items[0].kind != mediaKindImage {
		panic("kourtv2: a folder's image is an image, not a video link")
	}
	f.image = &items[0]
	emitModAct(c.id, 0, "folder-image", who)
}
func ClearFolderImage(cur realm, courtSlug string, folderID uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := requireFolderMod(c, who)
	cm.mustFolder(folderID).image = nil
	emitModAct(c.id, 0, "folder-image-clear", who)
}
func FolderImage(courtSlug string, folderID uint64) string {
	c := mustCourt(courtSlug)
	cm := c.mod
	if cm == nil {
		return "[]"
	}
	f := cm.mustFolder(folderID)
	if f.image == nil {
		return "[]"
	}
	return encodeMedia([]mediaItem{*f.image})
}
func PurgeFolder(cur realm, courtSlug string, folderID uint64, categoryCode string) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	d := ensureGlobalDAO()
	if !d.members.Has(who.String()) {
		panic("kourtv2: only a global DAO member may purge")
	}
	mustCategoryCode(categoryCode)
	c := mustCourt(courtSlug)
	cm := ensureMod(c)
	f := cm.mustFolder(folderID)
	fire, code := approveAction(d.pending, "purgefolder:"+c.id+":"+strconv.FormatUint(folderID, 10), who, categoryCode, d.purgeM)
	if !fire {
		return
	}
	f.purged = true
	f.code = code
	f.name = ""
	f.desc = ""
	f.image = nil
	emitPurge(c.id, 0, code, who)
}
func FolderCount(courtSlug string) int {
	c := mustCourt(courtSlug)
	if c.mod == nil {
		return 0
	}
	return c.mod.folders.Size()
}
func FolderName(courtSlug string, folderID uint64) string {
	c := mustCourt(courtSlug)
	if c.mod == nil {
		panic("kourtv2: no such folder")
	}
	f := c.mod.mustFolder(folderID)
	if f.purged {
		return "[purged:" + f.code + "]"
	}
	return f.name
}
func FolderDesc(courtSlug string, folderID uint64) string {
	c := mustCourt(courtSlug)
	if c.mod == nil {
		panic("kourtv2: no such folder")
	}
	return c.mod.mustFolder(folderID).desc
}
func FolderItems(courtSlug string, folderID uint64) []uint64 {
	c := mustCourt(courtSlug)
	if c.mod == nil {
		panic("kourtv2: no such folder")
	}
	f := c.mod.mustFolder(folderID)
	out := make([]uint64, len(f.items))
	copy(out, f.items)
	return out
}
func ClaimFolders(courtSlug string, claimID uint64) []uint64 {
	c := mustCourt(courtSlug)
	if c.mod == nil {
		return nil
	}
	var out []uint64
	for _, f := range c.mod.folderRows() {
		if f.purged {
			continue
		}
		for _, it := range f.items {
			if it == claimID {
				out = append(out, f.id)
				break
			}
		}
	}
	return out
}
func RetireFolder(cur realm, courtSlug string, folderID uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := requireFolderMod(c, who)
	f := cm.mustFolder(folderID)
	if cm.folderHeight(folderID) > 1 {
		panic("kourtv2: retire the folders inside it first")
	}
	f.retired = true
	f.items = nil
	emitModAct(c.id, 0, "folder-retire", who)
}
func RestoreFolder(cur realm, courtSlug string, folderID uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := requireFolderMod(c, who)
	f := cm.mustFolder(folderID)
	if f.purged {
		panic("kourtv2: a purged folder cannot be restored")
	}
	f.retired = false
	emitModAct(c.id, 0, "folder-restore", who)
}
func MoveItemInFolder(cur realm, courtSlug string, folderID, claimID uint64, to int) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := requireFolderMod(c, who)
	f := cm.mustFolder(folderID)
	at := -1
	for i, x := range f.items {
		if x == claimID {
			at = i
			break
		}
	}
	if at < 0 {
		panic("kourtv2: that claim is not in the folder")
	}
	if to < 0 || to >= len(f.items) {
		panic("kourtv2: that position is outside the folder")
	}
	if to == at {
		return
	}
	out := make([]uint64, 0, len(f.items))
	for i, x := range f.items {
		if i == at {
			continue
		}
		if len(out) == to {
			out = append(out, claimID)
		}
		out = append(out, x)
	}
	if len(out) == to {
		out = append(out, claimID)
	}
	f.items = out
	emitModAct(c.id, claimID, "folder-order", who)
}
func OrderFolders(cur realm, courtSlug string, parentID uint64, ids string) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	c := mustCourt(courtSlug)
	cm := requireFolderMod(c, who)
	if parentID != 0 {
		cm.mustFolder(parentID)
	}
	if len(ids) > maxFolders*21 {
		panic("kourtv2: that is too long to be a list of folder ids")
	}
	sibs := make([]*folder, 0, maxFolders)
	cm.folders.Iterate("", "", func(_ string, v any) bool {
		if f, ok := v.(*folder); ok && f.parent == parentID {
			sibs = append(sibs, f)
		}
		return false
	})
	if len(sibs) == 0 {
		panic("kourtv2: there are no folders under that heading to order")
	}
	parts := strings.Split(ids, ",")
	if len(parts) != len(sibs) {
		panic("kourtv2: that heading holds " + strconv.Itoa(len(sibs)) +
			" folders and the order lists " + strconv.Itoa(len(parts)) +
			"; it must list every one of them, exactly once")
	}
	order := make([]*folder, 0, len(parts))
	for _, p := range parts {
		id, err := strconv.ParseUint(strings.TrimSpace(p), 10, 64)
		if err != nil {
			panic("kourtv2: an order is a comma-separated list of folder ids")
		}
		var f *folder
		for _, s := range sibs {
			if s.id == id {
				f = s
				break
			}
		}
		if f == nil {
			panic("kourtv2: folder " + strconv.FormatUint(id, 10) +
				" is not under that heading")
		}
		for _, x := range order {
			if x.id == id {
				panic("kourtv2: folder " + strconv.FormatUint(id, 10) +
					" is listed twice")
			}
		}
		order = append(order, f)
	}
	for i, f := range order {
		f.ord = i + 1
	}
	emitModAct(c.id, 0, "folder-sort", who)
}
func FolderTree(courtSlug string) string {
	c := mustCourt(courtSlug)
	if c.mod == nil {
		return ""
	}
	var b strings.Builder
	n := 0
	for _, f := range c.mod.folderRows() {
		if n > 0 {
			b.WriteString(",")
		}
		flags := ""
		if f.retired {
			flags += "r"
		}
		if f.purged {
			flags += "p"
		}
		if f.focusByDefault {
			flags += "f"
		}
		if f.image != nil {
			flags += "i"
		}
		if flags == "" {
			flags = "-"
		}
		b.WriteString(strconv.FormatUint(f.id, 10) + ":" +
			strconv.FormatUint(f.parent, 10) + ":" + flags + ":" +
			strconv.FormatUint(f.bornOf, 10))
		n++
	}
	return b.String()
}
func FolderRetired(courtSlug string, folderID uint64) bool {
	c := mustCourt(courtSlug)
	if c.mod == nil {
		return false
	}
	v := c.mod.folders.Get(beClaimKey(folderID))
	if v == nil {
		return false
	}
	return v.(*folder).retired
}
func FolderParent(courtSlug string, folderID uint64) uint64 {
	c := mustCourt(courtSlug)
	if c.mod == nil {
		return 0
	}
	v := c.mod.folders.Get(beClaimKey(folderID))
	if v == nil {
		return 0
	}
	return v.(*folder).parent
}
func FolderPurged(courtSlug string, folderID uint64) bool {
	c := mustCourt(courtSlug)
	if c.mod == nil {
		panic("kourtv2: no such folder")
	}
	return c.mod.mustFolder(folderID).purged
}

package kourt2
import (
	"strconv"
	"strings"
	"chain"
)
const (
	setMark   = "\U00013080"
	shutMark  = "\U0001307C"
	setPrefix = setMark + " "
	shutPrefix = shutMark + " "
)
func parseSetTitle(title string) (name string, shown bool, ok bool) {
	pre := ""
	switch {
	case strings.HasPrefix(title, setPrefix):
		pre, shown = setPrefix, true
	case strings.HasPrefix(title, shutPrefix):
		pre, shown = shutPrefix, false
	default:
		return "", false, false
	}
	name = title[len(pre):]
	if !folderTextOK(name, "") {
		return "", false, false
	}
	return name, shown, true
}
func IsSetClaim(courtSlug string, claimID uint64) bool {
	cs := mustClaim(mustCourt(courtSlug), claimID)
	_, _, ok := parseSetTitle(cs.title)
	return ok
}
func ClaimSet(courtSlug string, claimID uint64) uint64 {
	c := mustCourt(courtSlug)
	if c.mod == nil || c.mod.folders == nil {
		return 0
	}
	var out uint64
	c.mod.folders.Iterate("", "", func(_ string, v any) bool {
		f := v.(*folder)
		if f.bornOf == claimID {
			out = f.id
			return true
		}
		return false
	})
	return out
}
func SetBornOf(courtSlug string, folderID uint64) uint64 {
	c := mustCourt(courtSlug)
	if c.mod == nil {
		return 0
	}
	return c.mod.mustFolder(folderID).bornOf
}
func New(cur realm, courtSlug string, claimID uint64) uint64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	name, shown, ok := parseSetTitle(cs.title)
	if !ok {
		panic("kourtv2: this claim's title is not a set heading")
	}
	if cs.verdictAt == 0 || cs.provClose {
		panic("kourtv2: no final verdict")
	}
	if cs.provisional != 0 {
		panic("kourtv2: the verdict was not YES")
	}
	if prior := ClaimSet(courtSlug, claimID); prior != 0 {
		panic("kourtv2: this claim already carries set " + strconv.FormatUint(prior, 10))
	}
	cm := ensureMod(c)
	if folderNameTaken(cm, name) {
		panic("kourtv2: a folder by that name already exists")
	}
	var parent uint64
	if in := ClaimFolders(courtSlug, claimID); len(in) == 1 {
		parent = in[0]
	} else if len(in) > 1 {
		panic("kourtv2: this claim is filed in more than one set; a born set needs exactly one parent")
	}
	if parent != 0 && cm.mustFolder(parent).retired {
		panic("kourtv2: the set this claim is filed in has been retired")
	}
	fid := newFolderCore(cm, name, "", parent)
	f := cm.mustFolder(fid)
	f.bornOf = claimID
	f.focusByDefault = shown
	emitModAct(c.id, claimID, "new", cs.author)
	chain.Emit("SetAffirmed",
		"court", c.id,
		"claim", strconv.FormatUint(claimID, 10),
		"folder", strconv.FormatUint(fid, 10),
		"parent", strconv.FormatUint(parent, 10),
		"name", name,
		"height", eventHeight(),
	)
	return fid
}

package kourt2
const topHoldersMax = 50
func HolderCount(courtSlug string) int {
	c := mustCourt(courtSlug)
	esc := c.escrow
	n := 0
	c.coin.WalkAccounts(func(who address, bal int64) bool {
		if bal > 0 && who != esc {
			n++
		}
		return false
	})
	return n
}
func TopHolders(courtSlug string, limit int) string {
	if limit <= 0 || limit > topHoldersMax {
		limit = topHoldersMax
	}
	c := mustCourt(courtSlug)
	esc := c.escrow
	who := make([]address, 0, limit)
	bal := make([]int64, 0, limit)
	c.coin.WalkAccounts(func(a address, b int64) bool {
		if b <= 0 || a == esc {
			return false
		}
		pos := len(who)
		for pos > 0 && b > bal[pos-1] {
			pos--
		}
		if pos >= limit {
			return false
		}
		if len(who) < limit {
			who = append(who, address(""))
			bal = append(bal, 0)
		}
		for i := len(who) - 1; i > pos; i-- {
			who[i], bal[i] = who[i-1], bal[i-1]
		}
		who[pos], bal[pos] = a, b
		return false
	})
	out := ""
	for i := range who {
		if bal[i] <= 0 {
			continue
		}
		out += ";" + string(who[i]) + ":" + itoa(bal[i])
	}
	if out == "" {
		return ""
	}
	return out[1:]
}
func TopHoldersNote() string {
	return "Ranked by coin held. Coin staked on a claim sits in the court's custody until the claim resolves, so it is not counted here."
}

package kourt2
import (
	"strconv"
	bptree "gno.land/p/nt/bptree/v0"
)
func lockedOf(c *Court, who address) int64 {
	if c.locked == nil {
		return 0
	}
	if v := c.locked.Get(string(who)); v != nil {
		return v.(int64)
	}
	return 0
}
func spendable(c *Court, who address) int64 {
	s := c.coin.BalanceOf(who) - lockedOf(c, who)
	if s < 0 {
		return 0
	}
	return s
}
func disposable(c *Court, who address) int64 {
	claim := lockedOf(c, who)
	if v := voteLockedOf(c, who); v > claim {
		claim = v
	}
	d := c.coin.BalanceOf(who) - claim
	if d < 0 {
		return 0
	}
	return d
}
func DisposableOf(courtSlug string, who address) int64 {
	return disposable(mustCourt(courtSlug), who)
}
func ccAmt(n int64) string {
	if n < 0 {
		return "-" + ccAmt(-n)
	}
	whole := strconv.FormatInt(n/1_000_000, 10)
	frac := n % 1_000_000
	if frac == 0 {
		return whole
	}
	f := strconv.FormatInt(frac, 10)
	for len(f) < 6 {
		f = "0" + f
	}
	for len(f) > 1 && f[len(f)-1] == '0' {
		f = f[:len(f)-1]
	}
	return whole + "." + f
}
func mustSpendable(c *Court, who address, amount int64) {
	if disposable(c, who) >= amount {
		return
	}
	vl, sl := voteLockedOf(c, who), lockedOf(c, who)
	short := "need " + ccAmt(amount) + " CC, you have " + ccAmt(disposable(c, who))
	switch {
	case vl <= 0 && sl <= 0:
		panic("kourtv2: not enough CC — " + short)
	case vl > sl:
		panic("kourtv2: not enough uncommitted CC — " + short +
			" free; " + ccAmt(vl) + " is committed by voting")
	case sl > vl:
		panic("kourtv2: not enough unstaked CC — " + short +
			" free; " + ccAmt(sl) + " is staked")
	default:
		panic("kourtv2: not enough free CC — " + short +
			" free; " + ccAmt(sl) + " is both staked and committed by voting")
	}
}
func mustStakable(c *Court, who address, amount int64) {
	if s := spendable(c, who); s < amount {
		tail := ""
		if l := lockedOf(c, who); l > 0 {
			tail = "; " + ccAmt(l) + " is staked"
		}
		panic("kourtv2: not enough unstaked CC — need " + ccAmt(amount) +
			" CC, you have " + ccAmt(s) + tail)
	}
}
func lockStake(c *Court, who address, amount int64) {
	if amount <= 0 {
		return
	}
	if c.locked == nil {
		c.locked = bptree.NewBPTree32()
	}
	c.locked.Set(string(who), mustAdd(lockedOf(c, who), amount))
}
func releaseStake(c *Court, who address, amount int64) {
	if amount <= 0 {
		return
	}
	l := lockedOf(c, who)
	if amount > l {
		panic("kourtv2: releasing more stake than is locked")
	}
	if amount == l {
		c.locked.Remove(string(who))
		return
	}
	c.locked.Set(string(who), l-amount)
}
func LockedOf(courtSlug string, who address) int64 {
	return lockedOf(mustCourt(courtSlug), who)
}
func SpendableOf(courtSlug string, who address) int64 {
	return spendable(mustCourt(courtSlug), who)
}
func TransferCC(cur realm, courtSlug string, to address, amount int64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	if amount <= 0 {
		panic("kourtv2: transfer amount must be positive")
	}
	from := cur.Previous().Address()
	if from == to {
		panic("kourtv2: cannot transfer to yourself")
	}
	c := mustCourt(courtSlug)
	if to == c.escrow || from == c.escrow {
		panic("kourtv2: the court escrow is not a transfer endpoint")
	}
	touch(c)
	mustSpendable(c, from, amount)
	c.coin.Transfer(from, to, amount)
}
func ApproveCC(cur realm, courtSlug string, spender address, amount int64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	if amount < 0 {
		panic("kourtv2: negative allowance")
	}
	c := mustCourt(courtSlug)
	owner := cur.Previous().Address()
	if spender == c.escrow || owner == c.escrow {
		panic("kourtv2: the court escrow is not a transfer endpoint")
	}
	touch(c)
	c.coin.Approve(owner, spender, amount)
}
func TransferFromCC(cur realm, courtSlug string, from, to address, amount int64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	if amount <= 0 {
		panic("kourtv2: transfer amount must be positive")
	}
	if from == to {
		panic("kourtv2: cannot transfer to yourself")
	}
	c := mustCourt(courtSlug)
	if to == c.escrow || from == c.escrow {
		panic("kourtv2: the court escrow is not a transfer endpoint")
	}
	touch(c)
	mustSpendable(c, from, amount)
	c.coin.TransferFrom(cur.Previous().Address(), from, to, amount)
}
func AllowanceCC(courtSlug string, owner, spender address) int64 {
	return mustCourt(courtSlug).coin.Allowance(owner, spender)
}

package kourt2
import (
	"chain"
	"strconv"
	"strings"
	sanitize "gno.land/p/nt/markdown/sanitize/v0"
)
func mediaDestination(m *mediaItem) string {
	if m.kind == mediaKindImage && m.sha256 != "" &&
		siteDomain != "" && siteDomainFault(siteDomain) == "" {
		return "https://" + siteDomain + "/m/" + m.sha256
	}
	for _, u := range m.mirrors {
		if mirrorFault(u) == "" {
			return u
		}
	}
	return ""
}
func verifyElsewhere() string {
	if siteDomain == "" || siteDomainFault(siteDomain) != "" {
		return ""
	}
	return " [" + siteDomain + "](https://" + siteDomain + ") checks it."
}
func writeClaimMedia(b *strings.Builder, c *Court, cs *claimState) {
	items := claimMediaVisible(c, cs)
	if len(items) == 0 {
		return
	}
	total := strconv.Itoa(len(items))
	b.WriteString("## Evidence filed with this claim\n\n")
	b.WriteString("_The court recorded a fingerprint of each image when the claim " +
		"was filed, so a swap can be detected — but not on this page._" + verifyElsewhere() + "\n\n")
	for i := range items {
		m := &items[i]
		pos := strconv.Itoa(i+1) + " of " + total
		if m.purged {
			b.WriteString("_Exhibit " + pos + " was taken down._\n\n")
			continue
		}
		dest := mediaDestination(m)
		if dest == "" {
			b.WriteString("_Exhibit " + pos + " is not currently available._\n\n")
			continue
		}
		caption := ""
		if m.caption != "" {
			caption = " — " + sanitize.InlineText(m.caption)
		}
		if m.kind == mediaKindVideo {
			b.WriteString("[▶ Exhibit " + pos + caption + "](" + dest +
				") _(a link; the court holds no copy and cannot vouch for it)_\n\n")
			continue
		}
		b.WriteString("![Exhibit " + pos + "](" + dest + ")\n\n")
		b.WriteString("_Exhibit " + pos + caption + "_\n\n")
	}
}
func ClaimMediaPage(courtSlug string, fromID uint64, count int) string {
	c := mustCourt(courtSlug)
	if count < 1 {
		return "[]"
	}
	if count > maxMediaPage {
		count = maxMediaPage
	}
	var b strings.Builder
	b.WriteString("[")
	for i := 0; i < count; i++ {
		if i > 0 {
			b.WriteString(",")
		}
		id := fromID + uint64(i)
		v := c.claims.Get(beClaimKey(id))
		if v == nil {
			b.WriteString("[]")
			continue
		}
		b.WriteString(encodeMedia(claimMediaVisible(c, v.(*claimState))))
	}
	b.WriteString("]")
	return b.String()
}
func PurgeClaimMedia(cur realm, courtSlug string, claimID uint64, idx uint64, categoryCode string) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	d := ensureGlobalDAO()
	if !d.members.Has(who.String()) {
		panic("kourtv2: only a global DAO member may purge")
	}
	mustCategoryCode(categoryCode)
	c := mustCourt(courtSlug)
	cs := mustClaim(c, claimID)
	if idx >= uint64(len(cs.media)) {
		panic("kourtv2: this claim carries no media item at that position")
	}
	if cs.media[idx].purged {
		return
	}
	fire, votedCode := approveAction(d.pending,
		"mediapurge:"+c.id+":"+strconv.FormatUint(claimID, 10)+":"+strconv.FormatUint(idx, 10),
		who, categoryCode, d.purgeM)
	if !fire {
		return
	}
	m := &cs.media[idx]
	m.purged = true
	m.sha256 = ""
	m.mirrors = nil
	m.caption = ""
	m.mime = ""
	ensureClaimMod(c, ensureMod(c), claimID).
		appendLog(who, boardActCode("media-purge", idx, votedCode), "")
	emitPurge(c.id, claimID, "media-item", who)
}
const (
	maxClaimMediaCount = 7
	maxMirrorsPerItem  = 4
	maxMediaURLLen     = 300
	maxCaptionLen      = 120
	maxMediaBytes = 262144
	maxMediaDim   = 20000
	maxMediaPage = 64
)
const (
	mediaKindImage = "img"
	mediaKindVideo = "vid"
)
type mediaItem struct {
	kind    string
	sha256  string
	mime    string
	w, h    int
	bytes   int
	caption string
	mirrors []string
	purged bool
}
func mediaCharFault(s string) string {
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < 0x21 || c > 0x7e {
			return "a mirror is printable ASCII with no spaces"
		}
		switch c {
		case '"', '\'', '<', '>', '(', ')', '\\', ',', '|', '`':
			return "a mirror may not contain " + string(rune(c))
		}
	}
	return ""
}
func isHexLower(s string) bool {
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') {
			continue
		}
		return false
	}
	return true
}
func mirrorFault(u string) string {
	if len(u) == 0 || len(u) > maxMediaURLLen {
		return "a mirror is 1.." + strconv.Itoa(maxMediaURLLen) + " characters"
	}
	if fault := mediaCharFault(u); fault != "" {
		return fault
	}
	const scheme = "https://"
	if !strings.HasPrefix(u, scheme) {
		return "a mirror is https — plain http is blocked as mixed content"
	}
	host := u[len(scheme):]
	for _, sep := range []byte{'/', '?', '#'} {
		if i := strings.IndexByte(host, sep); i >= 0 {
			host = host[:i]
		}
	}
	if host == "" {
		return "a mirror needs a host"
	}
	if !mediaHostAllowed(host) {
		return "the browser will not load images from " + host +
			"; see the allowed hosts on the help page"
	}
	return ""
}
var defaultMediaHostsExact = []string{
	"gnolang.github.io",
	"assets.gnoteam.com",
	"sa.gno.services",
	"imgur.com",
	"github.com",
	"imgflip.com",
	"ipfs.io",
	"cloudflare-ipfs.com",
}
var defaultMediaHostSuffixes = []string{
	".imgur.com",
	".github.io",
	".githubusercontent.com",
	".imgflip.com",
}
var mediaHostsExact = appendAll(nil, defaultMediaHostsExact)
var mediaHostSuffixes = appendAll(nil, defaultMediaHostSuffixes)
func appendAll(dst, src []string) []string {
	for _, v := range src {
		dst = append(dst, v)
	}
	return dst
}
const maxMediaHosts = 32
func mediaHostEntryFault(h string, suffix bool) string {
	if h == "" {
		return "a host may not be empty"
	}
	if len(h) > 100 {
		return "a host is at most 100 characters"
	}
	if suffix && h[0] != '.' {
		return "a suffix begins with a dot: " + h
	}
	if !suffix && h[0] == '.' {
		return "an exact host does not begin with a dot: " + h
	}
	for i := 0; i < len(h); i++ {
		c := h[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '-'
		if !ok {
			return "a host is lowercase letters, digits, dots and hyphens: " + h
		}
	}
	if strings.Contains(h, "..") || h[len(h)-1] == '.' {
		return "a host has no empty label: " + h
	}
	return ""
}
func parseMediaHosts(list string, suffix bool) []string {
	if strings.TrimSpace(list) == "" {
		return nil
	}
	parts := strings.Split(list, ",")
	if len(parts) > maxMediaHosts {
		panic("kourtv2: at most " + strconv.Itoa(maxMediaHosts) + " hosts in a list")
	}
	out := []string{}
	for _, p := range parts {
		h := strings.TrimSpace(p)
		if fault := mediaHostEntryFault(h, suffix); fault != "" {
			panic("kourtv2: " + fault)
		}
		for _, seen := range out {
			if seen == h {
				panic("kourtv2: " + h + " is listed twice")
			}
		}
		out = append(out, h)
	}
	return out
}
func SetMediaHosts(cur realm, exact, suffixes string) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	d := ensureGlobalDAO()
	if cur.Previous().Address() != d.admin {
		panic("kourtv2: only the global DAO admin sets the media hosts")
	}
	ex := parseMediaHosts(exact, false)
	sf := parseMediaHosts(suffixes, true)
	if len(ex) == 0 && len(sf) == 0 {
		panic("kourtv2: to allow no third-party host, call ClearMediaHosts")
	}
	mediaHostsExact = ex
	mediaHostSuffixes = sf
	chain.Emit(globalActEvent,
		"court", "*",
		"claim", "0",
		"act", "set-media-hosts:"+strconv.Itoa(len(ex))+"+"+strconv.Itoa(len(sf)),
		"by", cur.Previous().Address().String(),
		"height", eventHeight(),
	)
}
func ClearMediaHosts(cur realm) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	d := ensureGlobalDAO()
	if cur.Previous().Address() != d.admin {
		panic("kourtv2: only the global DAO admin sets the media hosts")
	}
	mediaHostsExact = nil
	mediaHostSuffixes = nil
	chain.Emit(globalActEvent,
		"court", "*",
		"claim", "0",
		"act", "clear-media-hosts",
		"by", cur.Previous().Address().String(),
		"height", eventHeight(),
	)
}
func MediaHosts() string {
	return strings.Join(mediaHostsExact, ",") + "|" + strings.Join(mediaHostSuffixes, ",")
}
func mediaHostAllowed(host string) bool {
	if host == "" {
		return false
	}
	if siteDomain != "" && host == siteDomain && siteDomainFault(siteDomain) == "" {
		return true
	}
	for _, h := range mediaHostsExact {
		if host == h {
			return true
		}
	}
	for _, s := range mediaHostSuffixes {
		if len(host) > len(s) && strings.HasSuffix(host, s) {
			return true
		}
	}
	return false
}
func captionFault(s string) string {
	if runeLen(s) > maxCaptionLen {
		return "a caption is at most " + strconv.Itoa(maxCaptionLen) + " characters"
	}
	for _, r := range s {
		if (r >= 0x202A && r <= 0x202E) || (r >= 0x2066 && r <= 0x2069) {
			return "a caption may not contain text-direction controls"
		}
	}
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\n', '\r':
			return "a caption is one line"
		case '|':
			return "a caption may not contain a vertical bar"
		}
		if s[i] < 0x20 && s[i] != '\t' {
			return "a caption may not contain control characters"
		}
	}
	return ""
}
func mediaItemFault(m *mediaItem) string {
	switch m.kind {
	case mediaKindImage:
		if len(m.sha256) != 64 || !isHexLower(m.sha256) {
			return "an image needs a sha256: 64 lowercase hex characters"
		}
		if m.w <= 0 || m.h <= 0 || m.w > maxMediaDim || m.h > maxMediaDim {
			return "an image needs real dimensions"
		}
		if m.bytes <= 0 || m.bytes > maxMediaBytes {
			return "an image is 1.." + strconv.Itoa(maxMediaBytes) + " bytes"
		}
		if m.mime == "" {
			return "an image needs a media type"
		}
	case mediaKindVideo:
		if m.sha256 != "" {
			return "a video link carries no hash"
		}
	default:
		return "a media item is " + mediaKindImage + " or " + mediaKindVideo
	}
	if fault := captionFault(m.caption); fault != "" {
		return fault
	}
	if len(m.mirrors) == 0 {
		return "a media item needs somewhere to find it"
	}
	if len(m.mirrors) > maxMirrorsPerItem {
		return "a media item lists at most " + strconv.Itoa(maxMirrorsPerItem) + " mirrors"
	}
	for _, u := range m.mirrors {
		if fault := mirrorFault(u); fault != "" {
			return fault
		}
	}
	return ""
}
func parseMediaFault(arg string) ([]mediaItem, string) {
	trimmed := strings.TrimSpace(arg)
	if trimmed == "" {
		return nil, ""
	}
	lines := strings.Split(trimmed, "\n")
	if len(lines) > maxClaimMediaCount {
		return nil, "a claim carries at most " +
			strconv.Itoa(maxClaimMediaCount) + " media items"
	}
	out := make([]mediaItem, 0, len(lines))
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		f := strings.Split(line, "|")
		if len(f) != 8 {
			return nil, "a media item has 8 fields separated by |"
		}
		m := mediaItem{
			kind:    f[0],
			sha256:  f[1],
			mime:    f[2],
			w:       atoiOr0(f[3]),
			h:       atoiOr0(f[4]),
			bytes:   atoiOr0(f[5]),
			caption: f[6],
		}
		for _, u := range strings.Split(f[7], ",") {
			if u != "" {
				m.mirrors = append(m.mirrors, u)
			}
		}
		if fault := mediaItemFault(&m); fault != "" {
			return nil, fault
		}
		out = append(out, m)
	}
	return out, ""
}
func parseMediaArg(arg string) []mediaItem {
	items, fault := parseMediaFault(arg)
	if fault != "" {
		panic("kourtv2: " + fault)
	}
	return items
}
func atoiOr0(s string) int {
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0
	}
	return n
}
func jsonString(s string) string {
	var b strings.Builder
	b.WriteString(`"`)
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if c < 0x20 {
				b.WriteString(`\u00`)
				const hex = "0123456789abcdef"
				b.WriteByte(hex[c>>4])
				b.WriteByte(hex[c&0xf])
				continue
			}
			b.WriteByte(c)
		}
	}
	b.WriteString(`"`)
	return b.String()
}
func encodeMedia(items []mediaItem) string {
	if len(items) == 0 {
		return "[]"
	}
	var b strings.Builder
	b.WriteString("[")
	for i := range items {
		if i > 0 {
			b.WriteString(",")
		}
		m := &items[i]
		b.WriteString(`{"kind":`)
		b.WriteString(jsonString(m.kind))
		if m.purged {
			b.WriteString(`,"purged":true}`)
			continue
		}
		b.WriteString(`,"sha256":`)
		b.WriteString(jsonString(m.sha256))
		b.WriteString(`,"mime":`)
		b.WriteString(jsonString(m.mime))
		b.WriteString(`,"w":`)
		b.WriteString(strconv.Itoa(m.w))
		b.WriteString(`,"h":`)
		b.WriteString(strconv.Itoa(m.h))
		b.WriteString(`,"bytes":`)
		b.WriteString(strconv.Itoa(m.bytes))
		b.WriteString(`,"caption":`)
		b.WriteString(jsonString(m.caption))
		b.WriteString(`,"mirrors":[`)
		n := 0
		for _, u := range m.mirrors {
			if mirrorFault(u) != "" {
				continue
			}
			if n > 0 {
				b.WriteString(",")
			}
			b.WriteString(jsonString(u))
			n++
		}
		b.WriteString(`]}`)
	}
	b.WriteString("]")
	return b.String()
}

package kourt2
import (
	"chain"
	"strconv"
	"strings"
	unsafe "chain/runtime/unsafe"
	"math/overflow"
	bptree "gno.land/p/nt/bptree/v0"
)
const metaRealmPath = "gno.land/r/g13khfsjnnq6g3lz2e997jejc9kvlz2x5yx08dr0/kourt2"
const (
	metaPrefix   = "mod:"
	metaCourtNm  = "Meta"
	metaExecuted = "MetaExecuted"
)
const (
	verbUnhide    = "unhide"
	verbClear     = "clear"
	verbHide      = "hide"
	verbSuspend   = "suspend"
	verbUnsuspend = "unsuspend"
	verbSetmods   = "setmods"
	verbNewset = "newset"
)
func verbIsAggressive(v string) bool {
	return v == verbHide || v == verbSuspend || v == verbUnsuspend || v == verbSetmods
}
type modParse struct {
	valid     bool
	verb      string
	court     string
	target    uint64
	hasTarget bool
	poisoned  bool
}
type metaState struct {
	parses   *bptree.BPTree
	bindings *bptree.BPTree
	latches  *bptree.BPTree
	executed *bptree.BPTree
}
var meta = &metaState{
	parses:   bptree.NewBPTree32(),
	bindings: bptree.NewBPTree32(),
	latches:  bptree.NewBPTree32(),
	executed: bptree.NewBPTree32(),
}
func init() {
	startCourt(unsafe.OriginCaller(), chain.PackageAddress(metaRealmPath), metaSlug, metaCourtNm, 0)
}
func parseModTitle(title string) modParse {
	p := modParse{}
	if !strings.HasPrefix(title, metaPrefix) {
		return p
	}
	rest := title[len(metaPrefix):]
	slash := strings.Index(rest, ":")
	if slash < 0 {
		return p
	}
	verb := rest[:slash]
	arg := rest[slash+1:]
	switch verb {
	case verbUnhide, verbClear, verbHide, verbSetmods, verbNewset:
		cut := strings.Index(arg, "/")
		if cut <= 0 || cut == len(arg)-1 {
			return p
		}
		id, err := strconv.ParseUint(arg[cut+1:], 10, 64)
		if err != nil || id == 0 {
			return p
		}
		p.court, p.target, p.hasTarget = arg[:cut], id, true
	case verbSuspend, verbUnsuspend:
		if arg == "" || strings.Contains(arg, "/") {
			return p
		}
		p.court = arg
	default:
		return p
	}
	for i := 0; i < len(p.court); i++ {
		ch := p.court[i]
		if !((ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') || ch == '-') {
			return modParse{}
		}
	}
	p.verb, p.valid = verb, true
	return p
}
func latchKey(p modParse) string {
	switch p.verb {
	case verbSetmods:
		return "set:" + p.court
	case verbNewset:
		return "fold:" + p.court
	case verbSuspend, verbUnsuspend:
		return "sus:" + p.court
	default:
		return "item:" + p.court + ":" + strconv.FormatUint(p.target, 10)
	}
}
func onClaimOpened(c *Court, cs *claimState) {
	if c.id != metaSlug {
		return
	}
	p := parseModTitle(cs.title)
	meta.parses.Set(beClaimKey(cs.id), &p)
	cs.noAccuracy = p.valid && p.verb == verbNewset
	if p.valid {
		pendingEnter(c, cs)
	}
}
func onTitleEdited(c *Court, cs *claimState) {
	if c.id != metaSlug {
		return
	}
	p := parseModTitle(cs.title)
	if prev := meta.parses.Get(beClaimKey(cs.id)); prev != nil && prev.(*modParse).poisoned {
		p.poisoned = true
	}
	meta.parses.Set(beClaimKey(cs.id), &p)
	cs.noAccuracy = p.valid && p.verb == verbNewset
	if p.valid || cs.seeded {
		pendingEnter(c, cs)
	} else {
		pendingExit(c, cs)
	}
}
func onClaimAnswered(c *Court, cs *claimState) {
	if c.id != metaSlug {
		return
	}
	v := meta.parses.Get(beClaimKey(cs.id))
	if v == nil {
		return
	}
	p := v.(*modParse)
	if !p.valid || p.poisoned {
		return
	}
	k := latchKey(*p)
	if held := meta.latches.Get(k); held != nil {
		if held.(uint64) != cs.id {
			panic("kourtv2: another appeal already holds this target's review slot")
		}
	}
	meta.latches.Set(k, cs.id)
	bind := *p
	meta.bindings.Set(beClaimKey(cs.id), &bind)
}
func releaseMetaLatchIfMeta(c *Court, cs *claimState) {
	if c.id != metaSlug {
		return
	}
	releaseMetaLatch(cs)
}
func releaseMetaLatch(cs *claimState) {
	v := meta.bindings.Get(beClaimKey(cs.id))
	if v == nil {
		return
	}
	k := latchKey(*v.(*modParse))
	if held := meta.latches.Get(k); held != nil && held.(uint64) == cs.id {
		meta.latches.Remove(k)
	}
}
func poisonMetaParse(claimID uint64) {
	if v := meta.parses.Get(beClaimKey(claimID)); v != nil {
		v.(*modParse).poisoned = true
	}
}
func metaVerdictExpired(cs *claimState, votingBlocks int64) bool {
	passed, known := pastDeadline(cs.verdictAtTime, blocksToSecs(votingBlocks)+1)
	return (known && passed) || (!known && heightNow() > cs.verdictAt+votingBlocks)
}
func ExecuteMetaVerdict(cur realm, metaClaimID uint64) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	mc := mustCourt(metaSlug)
	cs := mustClaim(mc, metaClaimID)
	bv := meta.bindings.Get(beClaimKey(metaClaimID))
	if bv == nil {
		panic("kourtv2: this claim carries no binding appeal")
	}
	p := *bv.(*modParse)
	if !Exists(p.court) {
		panic("kourtv2: the target court does not exist")
	}
	tc := mustCourt(p.court)
	if tc.createdAt >= cs.openedAt {
		panic("kourtv2: the target court does not predate this appeal")
	}
	var target *claimState
	if p.hasTarget && p.verb != verbSetmods && p.verb != verbNewset {
		target = mustClaim(tc, p.target)
		if target.openedAt >= cs.openedAt {
			panic("kourtv2: the target claim does not predate this appeal")
		}
	}
	if p.verb == verbSetmods {
		if cand := ensureMod(tc).mustCandidate(p.target); cand.at >= cs.openedAt {
			panic("kourtv2: the candidate set does not predate this appeal")
		}
	}
	if p.verb == verbNewset {
		if prop := ensureMod(tc).mustFolderProposal(p.target); prop.at >= cs.openedAt {
			panic("kourtv2: the folder proposal does not predate this appeal")
		}
	}
	if cs.verdictAt == 0 || cs.provClose {
		panic("kourtv2: no final verdict")
	}
	if int(cs.provisional) != sideYES {
		panic("kourtv2: the verdict was not YES")
	}
	if verbIsAggressive(p.verb) {
		if cs.route != "vote" || cs.decidedRounds == 0 {
			panic("kourtv2: this verb needs a decided contested vote, not silence")
		}
		if p.verb != verbHide && !cs.credEligible {
			panic("kourtv2: a manufactured contest cannot seize authority — this verb needs weight voted against it")
		}
	}
	if meta.executed.Has(beClaimKey(metaClaimID)) {
		panic("kourtv2: already executed")
	}
	if metaVerdictExpired(cs, mc.params.votingBlocks) {
		panic("kourtv2: this verdict has expired; re-appeal")
	}
	cm := ensureMod(tc)
	switch p.verb {
	case verbSetmods:
		if cm.setActHeight > cs.verdictAt {
			panic("kourtv2: the moderator set changed after this verdict; re-appeal")
		}
		if cm.suspended && cm.suspendActByGlobal > cs.openedAt {
			panic("kourtv2: the global DAO changed this court's suspension under this appeal; re-appeal")
		}
	case verbSuspend, verbUnsuspend:
		if cm.lastElectionAt > cs.openedAt || cm.setActHeight > cs.verdictAt {
			panic("kourtv2: the moderator set changed under this appeal; re-appeal")
		}
		if cm.suspendActByGlobal > cs.openedAt &&
			cm.suspended == (p.verb == verbUnsuspend) {
			panic("kourtv2: the global DAO changed this court's suspension under this appeal; re-appeal")
		}
	case verbUnhide:
		if cm.lastElectionAt > cs.openedAt {
			panic("kourtv2: the moderator set changed under this appeal; re-appeal")
		}
	}
	meta.executed.Set(beClaimKey(metaClaimID), true)
	applyMetaVerb(mc, tc, cm, p, cs, target)
	releaseMetaLatch(cs)
	chain.Emit(metaExecuted,
		"appeal", strconv.FormatUint(metaClaimID, 10),
		"verb", p.verb, "court", p.court,
		"target", strconv.FormatUint(p.target, 10),
	)
}
func applyMetaVerb(mc, tc *Court, cm *courtMod, p modParse, cs, target *claimState) {
	by := cs.answerer
	switch p.verb {
	case verbUnhide:
		clm := lookupClaimMod(cm, p.target)
		if clm == nil || !clm.court {
			return
		}
		clearCourtBitByMeta(tc, p.target, by)
	case verbClear:
		clearMetaBit(tc, p.target, by)
	case verbHide:
		setMetaBit(tc, p.target, by)
	case verbSuspend:
		suspendSet(tc, by)
	case verbUnsuspend:
		unsuspendSet(tc, by)
	case verbNewset:
		prop := cm.mustFolderProposal(p.target)
		if folderNameTaken(cm, prop.name) {
			panic("kourtv2: a folder by that name already exists")
		}
		if prop.parent != 0 {
			if pf := cm.mustFolder(prop.parent); pf.retired || pf.purged {
				panic("kourtv2: the parent heading is no longer in the tree")
			}
		}
		fid := newFolderCore(cm, prop.name, prop.desc, prop.parent)
		emitModAct(tc.id, 0, "folder-create", by)
		chain.Emit("FolderCreated",
			"court", tc.id, "by", "meta",
			"folder", strconv.FormatUint(fid, 10),
			"proposal", strconv.FormatUint(p.target, 10),
			"height", eventHeight(),
		)
	case verbSetmods:
		cand := cm.mustCandidate(p.target)
		installModSet(tc, cm, cand, heightNow(), false)
		chain.Emit("ModSetInstalled",
			"court", tc.id, "by", "meta",
			"candidate", strconv.FormatUint(cand.id, 10),
			"height", eventHeight(),
		)
	}
}
func AppealParse(claimID uint64) (verb, court string, target uint64, valid bool) {
	v := meta.parses.Get(beClaimKey(claimID))
	if v == nil {
		return "", "", 0, false
	}
	p := v.(*modParse)
	return p.verb, p.court, p.target, p.valid
}
func AppealExecuted(claimID uint64) bool { return meta.executed.Has(beClaimKey(claimID)) }
func AppealLatchHolder(verb, court string, target uint64) uint64 {
	p := modParse{verb: verb, court: court, target: target}
	if v := meta.latches.Get(latchKey(p)); v != nil {
		return v.(uint64)
	}
	return 0
}
var franchise = bptree.NewBPTree32()
func accrueFranchise(c *Court, who address, spent int64) {
	if c.id == metaSlug || spent <= 0 {
		return
	}
	k := who.String()
	prev := int64(0)
	if v := franchise.Get(k); v != nil {
		prev = v.(int64)
	}
	sum, ok := overflow.Add64(prev, spent)
	if !ok {
		return
	}
	franchise.Set(k, sum)
}
func ClaimMetaFranchise(cur realm) int64 {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	who := cur.Previous().Address()
	k := who.String()
	v := franchise.Get(k)
	if v == nil {
		return 0
	}
	owed := v.(int64)
	if owed <= 0 {
		return 0
	}
	mc := mustCourt(metaSlug)
	touch(mc)
	delta, used := mc.crv.Minted(mc.minted, owed)
	if delta <= 0 {
		return 0
	}
	mc.minted += delta
	recordPrice(mc)
	mc.coin.Mint(who, delta)
	if used >= owed {
		franchise.Remove(k)
	} else {
		franchise.Set(k, owed-used)
	}
	chain.Emit("FranchiseClaimed",
		"who", who.String(),
		"burned", strconv.FormatInt(used, 10),
		"minted", strconv.FormatInt(delta, 10),
	)
	return delta
}
func FranchiseOf(who address) int64 {
	if v := franchise.Get(who.String()); v != nil {
		return v.(int64)
	}
	return 0
}

package kourt2
import (
	"chain"
	"strconv"
	bptree "gno.land/p/nt/bptree/v0"
)
const (
	maxReasonLen = 200
	maxModSetSize = 32
	reSetWindowBlocks = int64(241_920)
	modActEvent    = "ModAct"
	globalActEvent = "GlobalAct"
	purgeEvent     = "Purge"
)
type daoState struct {
	admin   address
	members *bptree.BPTree
	n       int
	purgeM  int
	pending *bptree.BPTree
}
var globalDAO *daoState
const (
	daoBootstrapN = 1
	daoBootstrapM = 1
)
func ensureGlobalDAO() *daoState {
	if globalDAO != nil {
		return globalDAO
	}
	if directoryAdmin == "" {
		panic("kourtv2: no court exists yet; the global DAO has no admin")
	}
	d := &daoState{
		admin:   directoryAdmin,
		members: bptree.NewBPTree32(),
		n:       daoBootstrapN,
		purgeM:  daoBootstrapM,
		pending: bptree.NewBPTree32(),
	}
	d.members.Set(directoryAdmin.String(), true)
	globalDAO = d
	return d
}
func isGlobalMod(who address) bool {
	d := ensureGlobalDAO()
	return d.members.Has(who.String())
}
func AddGlobalMod(cur realm, who address) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	d := ensureGlobalDAO()
	if cur.Previous().Address() != d.admin {
		panic("kourtv2: only the global DAO admin manages membership")
	}
	seatGlobalMember(d, who)
}
func seatGlobalMember(d *daoState, who address) {
	if d.members.Has(who.String()) {
		return
	}
	d.members.Set(who.String(), true)
	d.n++
	clearPendingOnMembershipChange(&d.pending)
}
func RemoveGlobalMod(cur realm, who address) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	d := ensureGlobalDAO()
	if cur.Previous().Address() != d.admin {
		panic("kourtv2: only the global DAO admin manages membership")
	}
	if who == d.admin {
		panic("kourtv2: the admin cannot be removed; transfer admin first")
	}
	if d.members.Has(who.String()) {
		d.members.Remove(who.String())
		d.n--
		if d.purgeM > d.n {
			d.purgeM = d.n
		}
		clearPendingOnMembershipChange(&d.pending)
	}
}
func SetPurgeThreshold(cur realm, m int) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	d := ensureGlobalDAO()
	if cur.Previous().Address() != d.admin {
		panic("kourtv2: only the global DAO admin sets the purge threshold")
	}
	if m < 1 || m > d.n {
		panic("kourtv2: the purge threshold must be in 1..n")
	}
	if m != d.purgeM {
		clearPendingOnMembershipChange(&d.pending)
	}
	d.purgeM = m
}
func TransferGlobalAdmin(cur realm, to address) {
	if !cur.IsCurrent() {
		panic(errStaleRealm)
	}
	d := ensureGlobalDAO()
	if cur.Previous().Address() != d.admin {
		panic("kourtv2: only the global DAO admin transfers the seat")
	}
	seatGlobalMember(d, to)
	d.admin = to
}
